import {LANGS,KINDS,STATUS,clean,fold,same,snapshot,issues,status,filtered,totals,approve,canBulkApprove,validAnalysis,buildIndex,indexFor,fieldTextAudit} from './core.mjs';
import {generateSQL} from './sql-export.mjs';
import {migrationIndex,mergeIncoming,isEmbedded} from './dataset.mjs';
const $=s=>document.querySelector(s), app=$('#app'), overlay=$('#overlay');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number(v).toLocaleString('pt-BR');
const date=v=>new Date(v).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',layers:'m12 3 9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',form:'M6 3h12a1 1 0 0 1 1 1v16a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1 M9 8h6 M9 12h6 M9 16h4',fields:'M3 5h18v14H3z M3 10h18 M9 5v14',upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v5h16v-5',download:'M12 3v13 m-5-5 5 5 5-5 M4 16v5h16v-5',book:'M4 4h7a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H4z M14 7a3 3 0 0 1 3-3h4v14h-4a3 3 0 0 0-3 3',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l4 2',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',arrow:'M4 12h16 m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',search:'M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16 m6-2 5 5',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 11v6 M12 7h.01',link:'m10 13 4-4 M8 16l-2 2a4 4 0 0 1-6-6l4-4 M16 8l2-2a4 4 0 0 1 6 6l-4 4',menu:'M4 6h16 M4 12h16 M4 18h16',globe:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M2 12h20 M12 2c6 5 6 15 0 20-6-5-6-15 0-20',edit:'m15 4 5 5 M3 21l5-1L21 7l-5-5L3 15z',redo:'M4 10a8 8 0 1 1 2 9 M4 3v7h7',folder:'M3 7V4h7l3 3h8v14H3z',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-4 10 3 3 5-6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]??paths.grid}"/></svg>`;
const btn=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
let records=[],history=[],imports=[],db,live=false,liveModel='',storageOK=true,idx,datasetId='',dataAudit=null,filterCache=null;
function touch(){idx=buildIndex(records);filterCache=null;}
let view='catalog',kind='process',process='',form='',query='',state='all',problem='all',page=1,pageSize=10,selected=new Set(),queue=[],elementType='';
let toastTimer,importer,importData=null,lastFocus=null,job=null;
const byKey=k=>idx?.byKey.get(k)??records.find(r=>r.key===k);
const filter=()=>{const key=JSON.stringify([kind,process,form,query,state,problem,elementType]);if(filterCache?.key===key)return filterCache.rows;const rows=filtered(records,{kind,process,form,q:query,state,problem,elementType});filterCache={key,rows};return rows;};
const count=k=>idx?.byKind[k].length??0;
const selectedRecords=()=>{const keys=selected;return records.filter(r=>keys.has(r.key));};
const options=(items,value)=>items.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
const stat=(title,value,sub,i,c='')=>`<div class="stat"><div class="stat-top"><span>${title}</span><span class="stat-icon ${c}">${icon(i)}</span></div><div class="value">${n(value)}</div><small>${sub}</small></div>`;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),5000);}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('lexiflow-prototype-v1',1);req.onupgradeneeded=()=>{for(const name of ['records','history','meta'])req.result.createObjectStore(name,{keyPath:'key'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function readStore(name){return new Promise((resolve,reject)=>{const req=db.transaction(name).objectStore(name).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function save(changed=[],events=[],meta=false,replaceKind=null){if(!db){storageOK=false;return;}return new Promise((resolve,reject)=>{const tx=db.transaction(['records','history','meta'],'readwrite');const rs=tx.objectStore('records');const keys=new Set(changed.map(r=>r.key));if(replaceKind)for(const r of records.filter(r=>r.kind===replaceKind&&!keys.has(r.key)))rs.delete(r.key);for(const r of changed)rs.put(r);for(const h of events)tx.objectStore('history').put(h);if(meta)tx.objectStore('meta').put({key:'imports',value:imports});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error??new Error('Não foi possível salvar.'));});}
function shell(){return `<div class="shell"><aside class="sidebar" aria-label="Navegação principal"><div class="brand"><span class="brand-symbol">L</span>LexiFlow<sup>BETA</sup></div><div class="nav-label">Workspace</div><nav class="nav">${[['overview','grid','Visão geral'],['catalog','layers','Catálogo'],['imports','upload','Importações'],['glossary','book','Glossário'],['history','history','Histórico']].map(([v,i,l])=>`<button data-action="view" data-value="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${l}${v==='catalog'?`<span class="counter">${n(records.length)}</span>`:''}</button>`).join('')}</nav><div class="inventory"><div class="nav-label">Sua base</div>${Object.entries(KINDS).map(([k,l],i)=>`<div class="inventory-row"><i class="dot ${i===1?'teal':i===2?'orange':''}"></i><span>${l}</span><span>${n(count(k))}</span></div>`).join('')}</div><div class="side-bottom"><div class="next-card">${icon('link')}<strong>${count('field')?'Hierarquia disponível':'Complete os vínculos'}</strong><p>${count('field')?`${n(idx.forms.size)} IDs de formulário em ${n(idx.formPairs.size)} vínculos com processos.`:'Importe formulários e campos para revisar cada processo por completo.'}</p><button data-action="${count('field')?'view':'import'}" data-kind="form" data-value="imports">${count('field')?'Conferir a base':'Importar próxima base'} ${icon('arrow')}</button></div><div class="workspace"><div class="avatar">DTM</div><div><strong>Transformação Digital</strong><small>Revisão de nomenclaturas</small></div></div></div></aside><div class="content"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="mobile" aria-label="Abrir navegação">${icon('menu')}</button><span>Governança de processos</span>${icon('chevron')}<strong>${{overview:'Visão geral',catalog:'Revisão multilíngue',imports:'Importações',glossary:'Glossário',history:'Histórico'}[view]}</strong></div><div class="top-actions"><span class="prototype-tag">PROTÓTIPO INICIAL</span><button class="icon-button" data-action="connection" aria-label="Ver conexão da IA">${icon('globe')}</button><div class="avatar">TH</div></div></header><main id="main" class="main" tabindex="-1">${view==='catalog'?catalog():view==='overview'?overview():view==='imports'?importPage():view==='glossary'?glossaryPage():historyPage()}<footer class="footer"><span>${storageOK?'Dados e revisões salvos neste navegador. Exporte uma cópia para compartilhar.':'Armazenamento indisponível. Exporte sua revisão antes de fechar a página.'}</span><span>Nome original = EN · Nome PT = PT · Nome ES = ES</span></footer></main></div></div>`;}
function render(){if(!idx)touch();const focus=document.activeElement,restore=focus?.id,caret=focus?.selectionStart;app.innerHTML=shell();if(restore){const el=document.getElementById(restore);el?.focus({preventScroll:true});if(typeof caret==='number'&&el?.setSelectionRange)el.setSelectionRange(caret,caret);}}
function header(title,subtitle,actions='',eyebrow='CATÁLOGO MULTILÍNGUE'){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function statsHTML(list){const t=totals(list,idx);return `<div class="stats">${stat('Registros no filtro',t.total,`${n(t.unanalyzed)} sem revisão semântica`,'layers')}${stat('Corretos',t.ok,'Textos alinhados à revisão','check','green')}${stat('Precisam de ajuste',t.adjust,'Preenchimento, tradução ou padronização','edit','amber')}${stat('Revisar contexto',t.context,'Confirme significado ou identificação','alert','rose')}</div>`;}
function banner(){const scope=view==='catalog'?filter():idx.byKind[kind],complete=scope.filter(r=>r.analysis&&LANGS.every(l=>clean(r.analysis.suggested?.[l]))).length;return `<div class="insight"><div class="insight-main"><span class="insight-mark">${icon('spark')}</span><div><h2>Sugestões de revisão disponíveis</h2><p>${n(complete)} de ${n(scope.length)} ${KINDS[kind].toLowerCase()} com propostas nos três idiomas. Sugestões contextuais e de glossário são identificadas; textos incompletos ou sem tradução confiável ficam pendentes.</p></div></div><div class="insight-right"><span class="initial-tag">${live?'IA ao vivo conectada':'IA ao vivo ainda não conectada'}</span><button class="tiny-btn" data-action="connection">${live?'Ver conexão':'Como conectar'} ${icon('arrow')}</button></div></div>`;}

function hierarchyBar(){if(!process)return '';const p=idx.processes.get(process),forms=idx.formsByProcess.get(process)||[],fields=idx.fieldsByProcess.get(process)||[];return `<section class="hierarchy-bar" aria-label="Hierarquia do processo"><div><span class="hierarchy-code">${esc(process)}</span><strong>${esc(p?.current.pt||p?.current.original||process)}</strong><small>${n(new Set(forms.map(r=>r.id)).size)} IDs de formulário · ${n(fields.length)} registros de campos</small></div><div class="hierarchy-links">${[['process','Processo',1],['form','Formulários',forms.length],['field','Campos',fields.length]].map(([k,l,total])=>`<button class="hierarchy-item ${kind===k?'active':''}" data-action="tab" data-kind="${k}"><span>${l}</span><strong>${n(total)}</strong></button>`).join('')}</div></section>`;}
function diagnostics(){return `<div class="data-health"><span>${icon('link')}<strong>${n(idx.orphanKeys.size)}</strong> vínculos sem pai</span><button data-action="diagnostic" data-kind="field" data-problem="missing-id">${icon('info')}<strong>${n(idx.byKind.field.filter(r=>!r.id).length)}</strong> campos sem ID</button><button data-action="diagnostic" data-kind="form" data-problem="conflicts">${icon('alert')}<strong>${n(idx.conflictFormIds.size)}</strong> IDs de formulário com versões divergentes</button></div>`;}

function catalog(){const list=filter(),t=totals(list,idx),start=(page-1)*pageSize,pages=Math.max(1,Math.ceil(list.length/pageSize));if(page>pages)page=pages;const visible=list.slice((page-1)*pageSize,page*pageSize);const forms=process?(idx.formsByProcess.get(process)||[]):idx.byKind.form;const pItems=[['','Todos os processos'],...idx.byKind.process.map(r=>[r.id,`${r.id} · ${r.current.pt||r.current.original}`])];const fItems=[['','Todos os formulários'],...[...new Map(forms.map(r=>[r.id,[r.id,`${r.id||'Linha '+r.line} · ${r.current.pt||r.current.original}`]])).values()]];
 return header('Revisão multilíngue','Uma visão conectada dos nomes de processos, formulários e campos.',btn(icon('upload')+'Importar bases','import','',`data-kind="${kind}"`)+btn(icon('spark')+'Analisar com IA','analyze','primary'))+statsHTML(list)+banner()+hierarchyBar()+(!process&&kind==='process'?`<div class="pilot"><div><small>COMECE POR UM PROCESSO</small><strong><span class="pilot-code">CL002</span>Solicitar atendimento ao DBA</strong></div>${btn('Explorar processo '+icon('arrow'),'pilot','soft')}</div>`:'')+`<section class="panel" aria-label="Catálogo e sugestões"><div class="catalog-top"><div class="tabs" role="tablist" aria-label="Tipo de registro">${Object.entries(KINDS).map(([k,l])=>`<button class="tab ${kind===k?'active':''}" role="tab" aria-selected="${kind===k}" data-action="tab" data-kind="${k}">${icon(k==='process'?'layers':k==='form'?'form':'fields')}${l}<span class="tab-count">${n(count(k))}</span></button>`).join('')}</div><div class="catalog-meta">${n(t.approved)} aprovados · ${n(t.ptMissing)} sem PT · ${n(t.esMissing)} sem ES</div></div><div class="toolbar ${kind==='field'?'with-type':''}"><label class="search-field"><span class="field-label">BUSCAR NA SELEÇÃO</span><span class="search-wrap">${icon('search')}<input id="search" class="input" placeholder="ID, nome ou termo…" value="${esc(query)}" autocomplete="off"></span></label><label><span class="field-label">PROCESSO</span><select id="process-filter" class="input" aria-label="Filtrar processo">${options(pItems,process)}</select></label><label><span class="field-label">FORMULÁRIO</span><select id="form-filter" class="input" aria-label="Filtrar formulário" ${kind==='process'||!forms.length?'disabled':''}>${options(fItems,form)}</select></label>${kind==='field'?`<label><span class="field-label">TIPO DE ELEMENTO</span><select id="type-filter" class="input">${options([['','Todos os tipos'],...[...new Set(idx.byKind.field.map(r=>r.type))].sort().map(t=>[t,t])],elementType)}</select></label>`:''}<label class="status-filter"><span class="field-label">STATUS DA REVISÃO</span><select id="state-filter" class="input" aria-label="Filtrar status">${options([['all','Todos os status'],...Object.entries(STATUS)],state)}</select></label></div><div class="quick-filters"><div class="chips">${[['all','Todos'],['missing','Traduções ausentes'],['conflicts','Versões divergentes'],...(kind==='field'?[['missing-id','Sem ID de elemento'],['list','Listas / grids'],['limited','Possível corte na exportação']]:[['english','Original em PT/ES']]),['approved','Aprovados']].map(([p,l])=>`<button class="chip ${problem===p?'active':''}" data-action="problem" data-value="${p}">${l}</button>`).join('')}</div><span class="selection-hint">${icon('info')}Sugestões preservam os textos importados</span></div>${selected.size?`<div class="bulk"><strong>${n(selected.size)} selecionados</strong><button class="tiny-btn" data-action="select-filter">Selecionar todos do filtro</button><span class="spacer"></span>${btn('Revisar','review-selection','soft')}${btn(icon('check')+'Aprovar elegíveis','bulk-approve','primary')}<button class="icon-button bulk-clear" data-action="clear-selection" aria-label="Limpar seleção">${icon('close')}</button></div>`:''}${list.length?`<div class="table-wrap"><table class="review-table"><colgroup><col class="check-col"><col class="id-col">${Array.from({length:6},()=>'<col class="name-col">').join('')}<col class="status-col"></colgroup><thead><tr class="group-head"><th colspan="2"></th><th colspan="3">Dados atuais</th><th colspan="3" class="suggestion-head">${icon('spark')} Sugestões de revisão</th><th></th></tr><tr class="column-head"><th><input type="checkbox" data-action="select-page" aria-label="Selecionar esta página" ${visible.length&&visible.every(r=>selected.has(r.key))?'checked':''}></th><th>IDENTIFICADOR</th><th><span class="lang">EN</span>Nome original</th><th><span class="lang">PT</span>Nome PT</th><th><span class="lang">ES</span>Nome ES</th><th class="suggestion-head"><span class="lang">EN</span>Sugestão</th><th class="suggestion-head"><span class="lang">PT</span>Sugestão</th><th class="suggestion-head"><span class="lang">ES</span>Sugestão</th><th>STATUS</th></tr></thead><tbody>${visible.map(row).join('')}</tbody></table></div><div class="pagination"><span>${n((page-1)*pageSize+1)}–${n(Math.min(page*pageSize,list.length))} de ${n(list.length)} registros</span><div class="page-controls"><button class="icon-button" data-action="page" data-page="${page-1}" aria-label="Página anterior" ${page===1?'disabled':''}>${icon('left')}</button>${paginationButtons(page,pages)}<button class="icon-button" data-action="page" data-page="${page+1}" aria-label="Próxima página" ${page===pages?'disabled':''}>${icon('chevron')}</button></div><label>Por página <select id="page-size">${options([['10','10'],['25','25'],['50','50']],String(pageSize))}</select></label><button class="tiny-btn" data-action="export">${icon('download')}Exportar filtro</button></div>`:emptyCatalog()}</section>${kind!=='field'?`<div class="sql-action-bar"><div><strong>Atualizar os nomes no sistema de origem</strong><p>Gerar SQL de Nome original (EN), Nome PT e Nome ES para ${kind==='process'?'processos':'formulários'}.</p></div>${btn(icon('download')+'Script para atualização','sql-script','primary')}</div>`:''}`;
}
function paginationButtons(current,pages){const indices=[...new Set([1,...Array.from({length:5},(_,i)=>current-2+i).filter(x=>x>1&&x<pages),pages])].sort((a,b)=>a-b);return indices.map((p,i)=>`${i&&p-indices[i-1]>1?'<span>…</span>':''}<button class="page-number ${p===current?'active':''}" data-action="page" data-page="${p}" ${p===current?'aria-current="page"':''}>${p}</button>`).join('');}
function row(r){const s=status(r,idx);return `<tr class="${selected.has(r.key)?'selected':''}"><td><input type="checkbox" data-action="select-row" data-key="${esc(r.key)}" aria-label="Selecionar ${esc(r.id||'linha '+r.line)}" ${selected.has(r.key)?'checked':''}></td><td class="id-cell"><button data-action="review" data-key="${esc(r.key)}">${esc(r.id||'Linha '+r.line)} ${icon('chevron')}</button><small>${esc(r.kind==='process'?(r.cd?'CD '+r.cd:'Processo'):r.kind==='form'?r.processIds.join(', '):r.type+' · L'+r.line)}</small>${LANGS.some(k=>clean(r.list[k]))?'<span class="list-mark">+ termos de lista/grid</span>':''}</td>${LANGS.map(k=>`<td><span class="current-name">${clean(r.current[k])?esc(r.current[k]):'<span class="empty-value">Não preenchido</span>'}</span></td>`).join('')}${LANGS.map(k=>{const text=r.analysis?.suggested?.[k];return `<td class="suggestion">${text?esc(text):`<span class="empty-value">${r.analysis?'Requer tradução':'Aguardando análise'}</span>`}${text&&r.current[k]===text?`<span class="same-value">${icon('check')}Preservado</span>`:''}</td>`;}).join('')}<td class="status-cell"><span class="badge ${s}">${STATUS[s]}</span><button class="tiny-btn" data-action="review" data-key="${esc(r.key)}">${r.approval?'Ver revisão':'Revisar'} ${icon('arrow')}</button></td></tr>`;}
function emptyCatalog(){const has=count(kind)>0;return `<div class="empty"><div class="empty-art">${icon(kind==='field'?'fields':'form')}</div><h2>${has?'Nenhum registro neste filtro':kind==='form'?'Conecte os formulários aos processos':'Complete o contexto com os campos'}</h2><p>${has?'Ajuste os filtros para encontrar outros registros.':`A base de ${KINDS[kind].toLowerCase()} ainda não foi importada.${process?' O processo '+esc(process)+' está selecionado.':''} Seus dados reais aparecerão aqui após a importação.`}</p><div class="actions">${has?btn('Limpar filtros','reset-filter','soft'):btn(icon('upload')+`Importar ${KINDS[kind].toLowerCase()}`,'import','primary',`data-kind="${kind}"`)}${process?btn('Voltar ao processo','back-process'):''}</div></div>`;}
function overview(){const t=totals(records,idx);return header('Sua base, em três idiomas','Acompanhe a revisão e complete os vínculos entre processos, formulários e campos.',btn('Abrir catálogo '+icon('arrow'),'view','primary','data-value="catalog"'),'VISÃO GERAL')+statsHTML(records)+diagnostics()+banner()+`<div class="grid-2"><section class="section-card"><h2>Progresso da revisão</h2><p>A aprovação mantém um histórico dos textos anteriores.</p><div class="bar-line"><span>Aprovados</span><strong>${n(t.approved)} / ${n(t.total)}</strong></div><div class="bar"><i style="width:${t.total?t.approved/t.total*100:0}%"></i></div><div class="bar-line"><span>Português ainda ausente</span><strong>${n(t.ptMissing)}</strong></div><div class="bar"><i style="width:${t.total?t.ptMissing/t.total*100:0}%;background:#cfb78e"></i></div><div class="bar-line"><span>Espanhol ainda ausente</span><strong>${n(t.esMissing)}</strong></div><div class="bar"><i style="width:${t.total?t.esMissing/t.total*100:0}%;background:#bcaccf"></i></div></section><section class="section-card"><h2>Contexto completo, melhores sugestões</h2><p>Monte a hierarquia com os identificadores das três planilhas.</p>${Object.entries(KINDS).map(([k,l],i)=>`<div class="overview-step"><span class="step-num">${i+1}</span><div><strong>${l}</strong><small>${n(count(k))} registros ${k==='form'?`· ${n(idx.forms.size)} IDs distintos`:count(k)?'disponíveis':'· aguardando importação'}</small></div><button class="icon-button" data-action="${count(k)?'tab':'import'}" data-kind="${k}" aria-label="${count(k)?'Abrir':'Importar'} ${l}">${icon(count(k)?'arrow':'upload')}</button></div>`).join('')}</section></div><div class="notice">${icon('info')}<span>Os totais refletem os arquivos importados. Para confirmar que nenhum processo, formulário ou campo ficou de fora, concilie a base com uma exportação completa do sistema de origem.</span></div>`;}
function textLengthSummary(){const t=fieldTextAudit(idx.byKind.field);return `Os títulos originais chegam a ${n(t.maxOriginal)} caracteres; ${n(t.originalOver30)} ultrapassam 30. ${n(t.originalAt150)} títulos originais têm exatamente 150 caracteres. Considerando EN, PT, ES e termos de listas/grids, ${n(idx.limitedTitleKeys.size)} linhas atingem um limite observado na exportação e precisam de conferência na origem. O tamanho, por si só, não comprova corte. O portal preserva o texto integral recebido.`;}
function importPage(){return header('Importações','Mantenha os identificadores para conectar a hierarquia e preservar cada linha.',btn(icon('download')+'Cópia de segurança','backup'),'DADOS DE ORIGEM')+diagnostics()+`<div class="import-grid">${Object.entries(KINDS).map(([k,l])=>`<section class="section-card import-card"><span class="kind-icon">${icon(k==='process'?'layers':k==='form'?'form':'fields')}</span><h2>${l}</h2><p>${k==='process'?'ID Processo e nomes EN, PT e ES.':k==='form'?'ID Formulário e vínculo com ID Processo.':'ID Elemento e vínculo com ID Formulário. Termos de lista/grid são preservados.'}</p><div class="count">${n(count(k))}</div><small>${count(k)?k==='form'?`registros · ${n(idx.forms.size)} IDs distintos`:'registros na base':'aguardando sua planilha'}</small>${btn(icon('upload')+'Importar planilha','import','soft',`data-kind="${k}"`)}</section>`).join('')}</div><div class="notice">${icon('shield')}<span>Linhas sem identificador e IDs repetidos são preservados para revisão. Uma nova importação não recebe aprovação automática. Revise o mapeamento antes de confirmar.</span></div><section class="section-card data-card"><h2>Conferência da base</h2><p>${n(idx.processes.size)} IDs de processo, ${n(idx.forms.size)} IDs de formulário e ${n(idx.formPairs.size)} pares processo/formulário. Linhas de listas/grids e versões de traduções são preservadas como registros separados.</p><div class="notice">${icon('info')}<span>${textLengthSummary()}</span></div></section><section class="section-card data-card"><h2>Arquivos importados</h2><div class="table-wrap"><table class="simple-table"><thead><tr><th>Base</th><th>Arquivo</th><th>Registros</th><th>Importado em</th></tr></thead><tbody>${imports.map(i=>`<tr><td>${KINDS[i.kind]}</td><td>${esc(i.file)}</td><td>${n(i.count)}</td><td>${date(i.at)}</td></tr>`).join('')}</tbody></table></div></section><section class="section-card data-card"><h2>Restaurar uma cópia</h2><p>Reabra uma cópia JSON deste protótipo, com sugestões e histórico.</p><label class="btn" style="margin-top:15px;cursor:pointer">${icon('upload')}Selecionar cópia JSON<input id="restore-file" type="file" accept=".json" hidden></label></section>`;}
const glossary=[['DBA','Preservar sigla','Administrador de banco de dados. Traduzir a ação ao redor da sigla.'],['GMUD / DTM / CRM / SAP','Preservar siglas','Manter identificadores e siglas internas.'],['SoftExpert / SE Suite / Bitrix','Preservar nomes oficiais','Traduzir o contexto, preservando o nome do produto.'],['Customer Success','Nome de área','Confirmar o nome institucional adotado.'],['Price Builder 2.1 / BPMBOT','Confirmar nome de exibição','Não inventar uma ação para nomes técnicos.'],['Orçamento','Depende do contexto','Budget para planejamento financeiro; quote/quotation para proposta comercial.'],['Cobrança','Contexto financeiro','Collection / payment collection; cobro / gestión de cobros.'],['Downgrade','Contexto comercial','Redução de plano; cambio a un plan inferior.'],['Idioma / registro','Traduzir tudo para inglês corporativo','Pedido inicial. Base: histórico de traduções anexado (PDF: SoftExpert Suite, PLR, indicadores departamentais, aprovações, cadastros no DW).'],['Rótulos, campos e etapas de workflow','Title Case, curto e direto','Ex.: Approve Indicators, Verify Completion, Notify Requester.'],['Frases e instruções','Sentença completa, tom formal, ponto final','Ex.: Complete only if the indicator will use a different target for PLR purposes.'],['PLR / PLRCONTROL / PE029 / WF / DW / PMM / SoftExpert Suite','Preservar siglas e nomes','Também preservados nesta conversa: SAP, CRM, Pipedrive, OpenMeter, DHO, GSE, R&S, COO, BU, Senior, nomes de tabelas e campos (dyncttemptype, cttypename, idabreviation).'],['Nomes de campos entre aspas','Preservar','Ex.: "PLR Target", "Change Details", "Target".'],['Nomes próprios e marcas','Não traduzir','Silver Park, Uniparking, Green Park, GreenCar, Cesar, Tijucas, Brasil Cacau, Decacau, Cacau Show, Omunga, Prodent, GNC Cinemas, #CelebrateExpert.'],['Registro / Indicador / Responsável','Record / Indicator / Responsible','Terminologia padrão do histórico.'],['Reprovar / Desaprovar','Reject','Terminologia padrão do histórico.'],['Executor / Diretoria','Executor / Directorate (ou Board of Directors)','Escolher conforme o contexto.'],['Erros de digitação no original','Corrigir silenciosamente','Ex.: "dietor", "nome da soluçã".'],['Termo ambíguo','Escolher a opção mais provável pelo contexto','Avisar se houver alternativa relevante.'],['Termo já em inglês','Avisar que já está em inglês e pedir reenvio em português','Caso: Description of Actions Performed, Identity document, Head of Human Resources, Celebrate Expert.'],['Termo misto (PT + EN)','Traduzir por completo para inglês','Ex.: More info (receber) → More Info (Receive); Job request auxiliar → Auxiliary Job Request.'],['Nomes de campos pedidos em PT','Manter exatamente como no original','Título (PT-BR), Descrição (PT-BR); seções "Padrão para os termos", "Caracteres a serem evitados", "Padrão para a descrição".'],['Linguagem inclusiva','Evitar "he" / "ele" em perguntas de formulário','Ex.: Does this person have team members?; Eligible for Rehire?'],['Lista de eventos de desconto','Sem dois-pontos nas traduções; formato "<Item> Discount"','Pedido do usuário: remover o ":" (antes: "Discount: X").'],['Valores em reais','R$ 80,00 → R$ 80.00','Separador decimal em ponto no inglês.'],['Nomes de processos','Verbo primeiro, Title Case','Request Purchase; Request Travel and Submit Expense Report; Request Personnel Department Service.'],['Ocorrência','Occurrence','Usuário trocou "Incident" por "Occurrence".'],['Registro em espanhol','Espanhol corporativo neutro (México)','Formal “usted” em questionários; “tú” em mensagens entre colegas.'],['Dúvidas na tradução ES','Registrar em português','Uma linha curta após a tradução, começando com “Dúvida:”.'],['Termo decidido','Aplicar sempre','Depois que o usuário decide um termo, usar a mesma tradução dali em diante. Texto já em espanhol fica igual.'],['Avisos entre ** ... **','Manter os asteriscos','Terminar com ponto final.'],['Botões e ações (ES)','Infinitivo','Agregar, Eliminar, Aprobar, Enviar. Sufixos (Send)/(Receive)/(enviar)/(receber) viram (enviar)/(recibir).'],['Identificadores com underscore ou juntos','Traduzir só as palavras e manter o formato','director_approved? → director_aprobado?; requestanalysed → solicitudanalizada; verifyreturn → verificarretorno. Nomes técnicos fixos ficam iguais (OID Fake, dyncttemptype, cttypename, feature_key).'],['Prefixos de campo NM / NR / ID / VL / TP','Nombre / Número / Identificador / Valor / Tipo','Usar nas traduções para espanhol.'],['Chave técnica usada pelo OpenMeter para identificar a feature consumível. É a key consultada quando o front pergunta "quanto desse addon o tenant X já consumiu?".','Texto de ajuda · Addon OpenMeter','EN: Technical key used by OpenMeter to identify the consumable feature. It is the key queried when the front end asks, "How much of this add-on has tenant X already consumed?"'],['Sempre true. Mudar para false esconde o addon da tela e impede novos provisionamentos no sync. Útil para descontinuar um addon sem deletar o registro (preserva histórico).','Texto de ajuda · Addon OpenMeter','EN: Always true. Changing it to false hides the add-on from the screen and prevents new provisioning during sync. Useful for discontinuing an add-on without deleting the record (preserves history).'],['Nome interno/comercial do addon, aparece em logs e relatórios do OpenMeter, mas não é o que o cliente vê na tela.','Texto de ajuda · Addon OpenMeter','EN: Internal/commercial name of the add-on. It appears in OpenMeter logs and reports, but it is not what the customer sees on the screen.'],['Componente do addon.','Texto de ajuda · Addon OpenMeter','EN: Add-on component.'],['Os campos Título (PT-BR) e Descrição (PT-BR) correspondem a termos distintos. (mantenha o nome dos campos assim)','Texto de ajuda · Addon OpenMeter','EN: The fields Título (PT-BR) and Descrição (PT-BR) correspond to distinct terms. Nomes dos campos mantidos em PT.'],['Leia as seções "Padrão para os termos", "Caracteres a serem evitados" e "Padrão para a descrição" para garantir o correto preenchimento dos campos a seguir.','Texto de ajuda · Addon OpenMeter','EN: Read the sections "Padrão para os termos," "Caracteres a serem evitados," and "Padrão para a descrição" to ensure the following fields are completed correctly. Nomes das seções mantidos em PT.'],['Orientações sobre Termos','Texto de ajuda · Addon OpenMeter','EN: Guidelines on Terms.'],['Texto que aparece em destaque no card do addon.','Texto de ajuda · Addon OpenMeter','EN: Text displayed prominently on the add-on card.'],['Descrição para a criação de Termo:','Texto de ajuda · Addon OpenMeter','EN: Description for Term Creation:'],['Texto secundário no card que explica o addon ao cliente.','Texto de ajuda · Addon OpenMeter','EN: Secondary text on the card that explains the add-on to the customer.'],['Identificador do meter no OpenMeter, pode ser derivado automaticamente do feature_key ou informado manualmente para reutilizar um meter já existente.','Texto de ajuda · Addon OpenMeter','EN: Meter identifier in OpenMeter. It can be derived automatically from the feature_key or entered manually to reuse an existing meter.'],['Tipo de evento enviado pelo produto ao OpenMeter; pode ser derivado do feature_key ou informado manualmente quando o produto utiliza um tipo diferente.','Texto de ajuda · Addon OpenMeter','EN: Type of event sent by the product to OpenMeter; it can be derived from the feature_key or entered manually when the product uses a different type.'],['Define como os eventos serão consolidados para calcular o consumo: COUNT para contar eventos ou SUM para somar valores de uma propriedade do evento.','Texto de ajuda · Addon OpenMeter','EN: Defines how events will be consolidated to calculate consumption: COUNT to count events or SUM to add up values of an event property.'],['Caminho JSON da propriedade do evento que contém o valor numérico a ser somado no cálculo do consumo.','Texto de ajuda · Addon OpenMeter','EN: JSON path of the event property that contains the numeric value to be summed in the consumption calculation.'],['Define o ciclo de renovação dos créditos: MONTH para renovação mensal ou YEAR para renovação anual.','Texto de ajuda · Addon OpenMeter','EN: Defines the credit renewal cycle: MONTH for monthly renewal or YEAR for annual renewal.'],['Define de quanto em quanto a quantidade do addon pode ser comprada, usando um número inteiro maior ou igual a 1.','Texto de ajuda · Addon OpenMeter','EN: Defines the increment in which the add-on quantity can be purchased, using a whole number greater than or equal to 1.'],['Quantidade mínima de créditos que pode ser comprada para o addon.','Texto de ajuda · Addon OpenMeter','EN: Minimum quantity of credits that can be purchased for the add-on.'],['Anexe, no final do formulário, documentos contendo os detalhes da precificação.','Texto de ajuda · Addon OpenMeter','EN: Attach, at the end of the form, documents containing the pricing details.'],['Versão mínima da Suite a partir da qual o addon fica disponível.','Texto de ajuda · Addon OpenMeter','EN: Minimum Suite version from which the add-on becomes available.'],['Componentes da Suite necessários para que o cliente tenha acesso ao addon.','Texto de ajuda · Addon OpenMeter','EN: Suite components required for the customer to have access to the add-on.'],['Apresentação (Request)','Texto de ajuda · Addon OpenMeter','EN: Presentation (Request)'],['Sync com OpenMeter','Texto de ajuda · Addon OpenMeter','EN: Sync with OpenMeter.'],['Compra','Texto de ajuda · Addon OpenMeter','EN: Purchase.'],['Versionamento','Texto de ajuda · Addon OpenMeter','EN: Versioning.'],['Módulos Relacionados','Texto de ajuda · Addon OpenMeter','EN: Related Modules.'],['Detalhes da precificação','Texto de ajuda · Addon OpenMeter','EN: Pricing Details.'],['Documentação auxiliar','Texto de ajuda · Addon OpenMeter','EN: Supporting Documentation.'],['Ícone exibido no card do addon.','Texto de ajuda · Addon OpenMeter','EN: Icon displayed on the add-on card.'],['Módulo relacionado','Texto de ajuda · Addon OpenMeter','EN: Related Module.'],['Lista dos ícones','Texto de ajuda · Addon OpenMeter','EN: List of Icons.'],['contas a pagar / Contas a pagar','Workflow e rótulos','EN: Accounts Payable.'],['aprovador','Workflow e rótulos','EN: Approver.'],['Descrição das ações realizadas','Workflow e rótulos','EN: Description of Actions Performed. Já estava em inglês quando reenviado.'],['Workflow de Oferta Finalizado','Workflow e rótulos','EN: Offer Workflow Finalized. Primeira versão "Workflow Offer Finalized" corrigida (modificador antes do substantivo). Alternativa: Offer Workflow Completed.'],['conclusão','Workflow e rótulos','EN: Conclusion. Usuário pediu só a palavra.'],['WF Reprovado','Workflow e rótulos','EN: WF Rejected.'],['WF aberto pelo Diretor Comercial','Workflow e rótulos','EN: WF Opened by the Commercial Director.'],['Processos cancelados','Workflow e rótulos','EN: Cancelled Processes.'],['cancelados por mês','Workflow e rótulos','EN: Cancelled per Month.'],['faz parte da cadeia de valor?','Workflow e rótulos','EN: Is it part of the value chain?'],['Não instanciavel','Workflow e rótulos','EN: Not Instantiable.'],['Analise o material de marketing - PMC','Workflow e rótulos','EN: Analyze the Marketing Material - PMC.'],['Define Atributo','Workflow e rótulos','EN: Define Attribute.'],['Automação da instância do processo de PLR','Workflow e rótulos','EN: Automation of the PLR Process Instance.'],['Selecionar indicadores da área para PLR','Workflow e rótulos','EN: Select Area Indicators for PLR.'],['Sistema','Workflow e rótulos','EN: System.'],['Cancelar','Workflow e rótulos','EN: Cancel.'],['Inclusivo (OR)','Workflow e rótulos','EN: Inclusive (OR)'],['Exclusivo (XOR)','Workflow e rótulos','EN: Exclusive (XOR)'],['timerdebito','Workflow e rótulos','EN: Debit Timer.'],['Temporizador','Workflow e rótulos','EN: Timer.'],['Titulo02','Workflow e rótulos','EN: Title02.'],['Líder','Workflow e rótulos','EN: Leader.'],['Analista de comunicação','Workflow e rótulos','EN: Communications Analyst.'],['Jurídico','Workflow e rótulos','EN: Legal.'],['Iniciador','Workflow e rótulos','EN: Initiator.'],['Recrutador','Workflow e rótulos','EN: Recruiter.'],['Analista de DHO','Workflow e rótulos','EN: DHO Analyst.'],['Diretor financeiro','Workflow e rótulos','EN: Chief Financial Officer.'],['Head of Human Resources','Workflow e rótulos · Depende do contexto','EN: Já está em inglês. ES: Head de Recursos Humanos, Jefe de Recursos Humanos ou Director de Recursos Humanos.'],['Responsável pelo centro de custos','Workflow e rótulos','EN: Cost Center Manager.'],['Coordenador Administrativo','Workflow e rótulos','EN: Administrative Coordinator.'],['More info (receber) 2','Workflow e rótulos','EN: More Info (Receive) 2. Termo misto PT/EN.'],['More info (receber)','Workflow e rótulos','EN: More Info (Receive)'],['Retornar para o iniciante (dados inconsistentes)','Workflow e rótulos','EN: Return to Initiator (Inconsistent Data)'],['Término','Workflow e rótulos','EN: End.'],['Retornar','Workflow e rótulos','EN: Return.'],['Seguir','Workflow e rótulos','EN: Continue.'],['Prosseguir','Workflow e rótulos','EN: Proceed.'],['Finalizador','Workflow e rótulos','EN: Finalizer.'],['Receber','Workflow e rótulos','EN: Receive.'],['Complexo','Workflow e rótulos','EN: Complex.'],['verificaretorno','Workflow e rótulos','EN: Verify Return.'],['Retorno (A)','Workflow e rótulos','EN: Return (A)'],['Notificar (B)','Workflow e rótulos','EN: Notify (B)'],['Link (enviar)','Workflow e rótulos','EN: Link (Send)'],['Link (receber)','Workflow e rótulos','EN: Link (Receive)'],['Arquivo','Workflow e rótulos','EN: File.'],['critico','Workflow e rótulos','EN: Critical.'],['Texto','Workflow e rótulos','EN: Text.'],['Quantidade','Workflow e rótulos','EN: Quantity.'],['Empresa','Workflow e rótulos','EN: Company.'],['Alterar empresa','Workflow e rótulos','EN: Change Company.'],['Horas totais','Workflow e rótulos','EN: Total Hours.'],['Solicitação sem subprocesso','Workflow e rótulos','EN: Request Without Subprocess.'],['Solicitação com subprocesso','Workflow e rótulos','EN: Request With Subprocess.'],['Demanda realizada','Workflow e rótulos','EN: Request Completed.'],['Reprovar','Workflow e rótulos','EN: Reject.'],['Alterar dados do expert (receber)','Desligamento e cadastro','EN: Change Expert Data (Receive)'],['Efetivação / troca de vínculo','Desligamento e cadastro','EN: Effectuation / Relationship Change. Versão curta, a pedido (antes: ... Change of Employment Relationship).'],['Será para a efetivação ou troca de vínculo?','Desligamento e cadastro','EN: Will this be for effectuation or change of employment relationship?'],['Pode ser recontratado futuramente?','Desligamento e cadastro','EN: Eligible for Rehire? Rótulo do campo no formulário GPE00010; versão anterior "Can he be rehired in the future?" evitada (pronome). Variação curta: Rehire Eligibility.'],['Comunicar R&S sobre desligamento de lider','Desligamento e cadastro','EN: Notify R&S of Leader Termination.'],['Desativar cadastro no senior','Desligamento e cadastro','EN: Deactivate Registration in Senior.'],['Enviar código','Desligamento e cadastro','EN: Send Code.'],['Enviar questionário','Desligamento e cadastro','EN: Send Questionnaire.'],['Enviar questionário EN','Desligamento e cadastro','EN: Send Questionnaire EN.'],['Atualizar site','Desligamento e cadastro','EN: Update Website.'],['Atualizar site (receber)','Desligamento e cadastro','EN: Update Website (Receive)'],['Solicitar rescisão de contrato (receber)','Desligamento e cadastro','EN: Request Contract Termination (Receive)'],['Atualizar crm e pipedrive (receber)','Desligamento e cadastro','EN: Update CRM and Pipedrive (Receive)'],['ativos','Desligamento e cadastro','EN: Assets.'],['tesouraria','Desligamento e cadastro','EN: Treasury.'],['Iniciativa do desligamento','Desligamento e cadastro','EN: Termination Initiative.'],['Idioma para enviar o questionário','Desligamento e cadastro','EN: Language to Send the Questionnaire.'],['E-mail particular','Desligamento e cadastro','EN: Personal Email.'],['Comentários/Pendências','Desligamento e cadastro','EN: Comments/Pending Items.'],['Solicitar alteração de dados','Desligamento e cadastro','EN: Request Data Change.'],['He has team members? ("precisa ficar sem que pareça ELE")','Desligamento e cadastro','EN: Does this person have team members? Alternativa de RH: Does this employee have direct reports?'],['Prazo para permanecer os acessos atuais','Desligamento e cadastro','EN: Deadline for Current Access to Remain Active.'],['Justificativa pelo acessos temporários','Desligamento e cadastro','EN: Justification for Temporary Access.'],['Justificativa pela continuação de acessos','Desligamento e cadastro','EN: Justification for Continued Access.'],['Nome novo?','Desligamento e cadastro','EN: New Name? EN: New Name.'],['Criar / Alterar Centro de custos','Desligamento e cadastro','EN: Create/Change Cost Center.'],['Funções','Desligamento e cadastro','EN: Functions.'],['Alterações','Desligamento e cadastro','EN: Changes.'],['Função já existente','Desligamento e cadastro','EN: Role Already Exists.'],['Nova função','Desligamento e cadastro','EN: New Role. EN: New Role?'],['Entrevista','Entrevista de saída','EN: Interview.'],['Qual fator foi decisivo para motivar sua saída?','Entrevista de saída','EN: What factor was decisive in motivating your departure?'],['A empresa poderia ter feito algo para evitar sua saída?','Entrevista de saída','EN: Could the company have done something to prevent your departure?'],['Gostaria de comentar para qual empresa está indo?','Entrevista de saída','EN: Would you like to share which company you\'re going to?'],['Detalhes da empresa','Entrevista de saída','EN: Company Details.'],['Em uma escala de 0 a 10, qual a nota você atribuiria para o ambiente organizacional da SoftExpert:','Entrevista de saída','EN: On a scale of 0 to 10, what score would you give to SoftExpert\'s organizational environment:'],['Comente a nota da questão anterior','Entrevista de saída','EN: Comment on the Score from the Previous Question. Usado duas vezes (ambiente e desenvolvimento).'],['O que você pode nos contar de positivo sobre sua experiência conosco?','Entrevista de saída','EN: What positive feedback can you share about your experience with us?'],['O que você pode nos contar sobre pontos acha que podem ser melhorados na empresa?','Entrevista de saída','EN: What can you tell us about points you think could be improved in the company?'],['Em uma escala de 0 a 10, o quanto você acredita ter recebido oportunidades suficientes de desenvolvimento profissional na SoftExpert:','Entrevista de saída','EN: On a scale of 0 to 10, how much do you believe you received sufficient opportunities for professional development at SoftExpert:'],['Na sua opinião, acredita que a empresa oferece reconhecimento profissional?','Entrevista de saída','EN: In your opinion, do you believe the company offers professional recognition?'],['Detalhes - Na sua opinião, acredita que a empresa oferece reconhecimento profissional?','Entrevista de saída','EN: Details - In Your Opinion, Do You Believe the Company Offers Professional Recognition?'],['Você recebia da sua liderança feedbacks sobre a sua evolução e desempenho?','Entrevista de saída','EN: Did you receive feedback from your leadership about your evolution and performance?'],['Detalhes - Você recebia da sua liderança feedbacks sobre a sua evolução e desempenho?','Entrevista de saída','EN: Details - Did You Receive Feedback from Your Leadership About Your Evolution and Performance?'],['Você recebia orientação e suporte necessário quanto as metas e objetivos atribuídos a você?','Entrevista de saída','EN: Did you receive the necessary guidance and support regarding the goals and objectives assigned to you?'],['Detalhes - Você recebia orientação e suporte necessário quanto as metas e objetivos atribuídos a você? Comente','Entrevista de saída','EN: Details - Did You Receive the Necessary Guidance and Support Regarding the Goals and Objectives Assigned to You? Please Comment.'],['Qual é a probabilidade de você nos recomendar a um amigo ou a um colega?','Entrevista de saída','EN: How likely are you to recommend us to a friend or colleague?'],['Resumo para liderança','Entrevista de saída','EN: Summary for Leadership.'],['Mochila Expert: R$ 80,00','Benefícios e onboarding','EN: Expert Backpack: R$ 80.00.'],['Uniforme Padrão Onboarding: R$ 13,00','Benefícios e onboarding','EN: Standard Onboarding Uniform: R$ 13.00.'],['Confirma entrega de itens/quantidade conforme chamado','Benefícios e onboarding','EN: Confirms Delivery of Items/Quantity as per Ticket.'],['Identity document','Benefícios e onboarding','EN: Já está em inglês.'],['Estacionamento','Benefícios e onboarding','EN: Parking.'],['O ingresso é digital e pode ser utilizado para compra online. | O ingresso é enviado pelo RH através do próprio workflow e você recebe no seu e-mail | Mais informações, consultar Portal do Expert Brasil - Convênios.','Benefícios e onboarding','EN: The ticket is digital and can be used for online purchases. | The ticket is sent by HR through the workflow itself, and you will receive it by email. | For more information, check the Expert Brazil Portal - Partnerships.'],['Ingressos GNC Cinemas','Benefícios e onboarding','EN: GNC Cinemas Tickets.'],['Numeração digital do ingresso:','Benefícios e onboarding','EN: Digital Ticket Number:'],['Vales de transporte','Benefícios e onboarding','EN: Transportation Vouchers.'],['Competência','Depende do contexto','EN: Reference Period (folha) ou Competency (habilidades) Reference Period: mês/período de competência em RH e folha. Competency: habilidades profissionais.'],['Deseja abonar até 1/3 das suas férias?','Benefícios e onboarding','EN: Would you like to sell up to 1/3 of your vacation days?'],['Deseja receber adiantamento de 13º salário?','Benefícios e onboarding','EN: Would you like to receive an advance on your 13th salary?'],['Solicitações com desconto em folha','Benefícios e onboarding','EN: Requests with Payroll Deduction.'],['Envio de ingressos','Benefícios e onboarding','EN: Ticket Delivery.'],['Celebrate Expert','Benefícios e onboarding','EN: Já está em inglês.'],['WF aberto por diretor?','Recrutamento e vagas','EN: WF Opened by a Director? EN: WF Opened by a Director.'],['Define aprovador','Recrutamento e vagas','EN: Define Approver.'],['Aprovar COO - BU','Recrutamento e vagas','EN: Approve COO - BU.'],['Aprovar solicitação de emprego','Recrutamento e vagas','EN: Approve Job Request.'],['Substituição','Recrutamento e vagas','EN: Replacement.'],['Aprovar orçamento','Recrutamento e vagas','EN: Approve Budget. Orçamento: Budget (planejamento) / quote (proposta comercial), conforme contexto.'],['Recrutar Expert','Recrutamento e vagas','EN: Recruit Expert.'],['Alteração de dados da vaga','Recrutamento e vagas','EN: Job Opening Data Change.'],['Selecionar vaga','Recrutamento e vagas','EN: Select Job Opening.'],['Nome do candidato','Recrutamento e vagas','EN: Candidate Name.'],['Data de inicío','Recrutamento e vagas','EN: Start Date.'],['Candidato iniciará de fato?','Recrutamento e vagas · Decidido para ES','EN: Will the Candidate Actually Start? ES: ¿El candidato ingresará efectivamente? Fixo.'],['Job request auxiliar','Recrutamento e vagas','EN: Auxiliary Job Request. Termo misto PT/EN.'],['Canal de Denúncias','Tratar Denúncia (CO003)','EN: Whistleblower Channel.'],['Não instaurar','Tratar Denúncia (CO003)','EN: Do Not Establish. Rótulo do ramo após "Analyze and Treat Demand" que leva direto ao Closure. Decisão do usuário.'],['Preparar medida disciplinar','Tratar Denúncia (CO003)','EN: Prepare Disciplinary Action.'],['Notificar líder','Tratar Denúncia (CO003)','EN: Notify Leader.'],['Aplicar medida disciplinar','Tratar Denúncia (CO003)','EN: Apply Disciplinary Action.'],['Registrar medida na ficha do expert','Tratar Denúncia (CO003)','EN: Record Action in the Expert\'s File.'],['Ocorrência - Relação de Pessoas Sujeitas a Medidas Disciplinares','Tratar Denúncia (CO003)','EN: Occurrence – List of Individuals Subject to Disciplinary Action. "Ocorrência" = Occurrence (decisão do usuário).'],['Muy grave','Tratar Denúncia (CO003)','EN: Very Serious. Escala de gravidade (ES → EN).'],['Grave','Tratar Denúncia (CO003)','EN: Serious.'],['Poco grave','Tratar Denúncia (CO003)','EN: Minor.'],['Acidental','Tratar Denúncia (CO003)','EN: Accidental.'],['Intencional / Maliciosa','Tratar Denúncia (CO003)','EN: Intentional / Malicious.'],['Advertência Escrita','Tratar Denúncia (CO003)','EN: Written Warning.'],['Amonestación verbal','Tratar Denúncia (CO003)','EN: Verbal Warning. ES → EN.'],['Suspensão Temporária','Tratar Denúncia (CO003)','EN: Temporary Suspension.'],['Rescisão de Contrato de Trabalho por Justa Causa','Tratar Denúncia (CO003)','EN: Termination of Employment Contract for Cause.'],['Data de aplicação da medida','Tratar Denúncia (CO003)','EN: Date Action Was Applied.'],['Describa cómo se aplicó la medida','Tratar Denúncia (CO003)','EN: Describe How the Action Was Applied. ES → EN.'],['Solicitar viagem e Prestar contas (nome de processo)','Departamento Pessoal','EN: Request Travel and Submit Expense Report.'],['Solicitar compra (nome de processo)','Departamento Pessoal','EN: Request Purchase.'],['Solicitar serviço de Departamento Pessoal','Departamento Pessoal','EN: Request Personnel Department Service.'],['Outros serviços','Departamento Pessoal','EN: Other Services.'],['Férias','Departamento Pessoal','EN: Vacation.'],['Férias não aprovadas','Departamento Pessoal','EN: Vacation Not Approved.'],['Ferias aprovadas?','Departamento Pessoal','EN: Vacation Approved?'],['Férias/ Solicitação reprovadas','Departamento Pessoal','EN: Vacation / Request Rejected.'],['Notificar DP','Departamento Pessoal','EN: Notify Personnel Department. DP = Departamento Pessoal (não mantida a sigla).'],['Solicitar análise jurídica','Departamento Pessoal','EN: Request Legal Review.'],['FORMULÁRIO CONTRATOS','Contratos','EN: CONTRACTS FORM.'],['Existe workflow de venda (SSO)? Há formalização do aceite pelo cliente? Se não, descrever motivo.','Contratos','EN: Is there a sales workflow (SSO)? Is there formal acceptance by the customer? If not, describe the reason.'],['Condição de Pagamento está de acordo com Proposta Comercial (Valores, produtos, parcelamentos)?','Contratos','EN: Does the Payment Term comply with the Commercial Proposal (Amounts, Products, Installments)?'],['Contrato estabelece alguma obrigação acessória referente ao faturamento (retenções, prazos, necessidade de acessar portais)?','Contratos','EN: Does the contract establish any ancillary obligations regarding invoicing (withholdings, deadlines, need to access portals)?'],['Se sim, foi alinhado com a área financeira?','Contratos','EN: If so, was it aligned with the Finance department? Enviado duas vezes.'],['Contrato estabelece obrigação de contratar seguro garantia?','Contratos','EN: Does the contract establish an obligation to take out surety insurance?'],['Se sim, foi contratado?','Contratos','EN: If so, has it been taken out?'],['Valor cadastrado na tabela dyncttemptype, campo cttypename. Valor utilizado para registrar o tipo de contrato no formulário Customer e afins.','Cadastro técnico','EN: Value stored in the dyncttemptype table, field cttypename. Value used to record the contract type in the Customer form and similar forms. Tabela, campo e nome do formulário preservados.'],['Valor cadastrado na tabela dyncttemptype, campo idabreviation. Valor utilizado para registrar o tipo de contrato no formulário Customer e afins.','Cadastro técnico','EN: Value stored in the dyncttemptype table, field idabreviation. Value used to record the contract type in the Customer form and similar forms.'],['Valor cadastrado no SAP para registro e faturamento do produto.','Cadastro técnico','EN: Value stored in SAP for product registration and billing.'],['Desconto compras Feiras Chocolate Brasil Cacau','Evento de desconto','EN: Brasil Cacau Chocolate Fair Purchases Discount; ES: Descuento Compras en Ferias de Chocolate Brasil Cacau.'],['Desconto Pagamentos Indevidos','Evento de desconto','EN: Improper Payments Discount; ES: Descuento Pagos Indebidos.'],['Mensalidade Estacionamento Silver Park','Evento de desconto','EN: Silver Park Parking Monthly Fee; ES: Cuota Mensual de Estacionamiento Silver Park.'],['Mensalidade Estacionamento Uniparking','Evento de desconto','EN: Uniparking Parking Monthly Fee; ES: Cuota Mensual de Estacionamiento Uniparking.'],['Mensalidade Estacionamento Green Park','Evento de desconto','EN: Green Park Parking Monthly Fee; ES: Cuota Mensual de Estacionamiento Green Park.'],['Desconto Lavação GreenCar','Evento de desconto','EN: GreenCar Car Wash Discount; ES: Descuento Lavado GreenCar.'],['Desconto Ligações Telefônicas','Evento de desconto','EN: Phone Calls Discount; ES: Descuento Llamadas Telefónicas.'],['Desconto Eventos GSE (2)','Evento de desconto','EN: GSE Events Discount (2); ES: Descuento Eventos GSE (2).'],['Desconto Compras Brindes','Evento de desconto','EN: Promotional Items Purchases Discount; ES: Descuento Compras de Artículos Promocionales.'],['Desconto Outras Despesas Administrativas','Evento de desconto','EN: Other Administrative Expenses Discount; ES: Descuento Otros Gastos Administrativos.'],['Desconto Eventos Softexpert','Evento de desconto','EN: SoftExpert Events Discount; ES: Descuento Eventos SoftExpert.'],['Desc Reparo Equipamentos','Evento de desconto','EN: Equipment Repair Discount; ES: Descuento Reparación de Equipos.'],['Desconto Eventos GSE (esportes)','Evento de desconto','EN: GSE Events Discount (Sports); ES: Descuento Eventos GSE (Deportes).'],['Desconto Lavação Cesar','Evento de desconto','EN: Cesar Car Wash Discount; ES: Descuento Lavado Cesar.'],['Desconto Dif #CelebrateExpert','Evento de desconto','EN: #CelebrateExpert Difference Discount; ES: Descuento Diferencia #CelebrateExpert.'],['Desconto Ações Sociais','Evento de desconto','EN: Social Actions Discount; ES: Descuento Acciones Sociales.'],['Desconto Eventos GSE Parcelados','Evento de desconto','EN: GSE Events Discount (Installments); ES: Descuento Eventos GSE (Cuotas).'],['Desconto compras Feiras Chocolate Decacau','Evento de desconto','EN: Decacau Chocolate Fair Purchases Discount; ES: Descuento Compras en Ferias de Chocolate Decacau.'],['Mensalidade GSE','Evento de desconto','EN: GSE Monthly Fee; ES: Cuota Mensual GSE.'],['Desconto aquisições produtos Omunga','Evento de desconto','EN: Omunga Product Purchases Discount; ES: Descuento Compras de Productos Omunga.'],['Desconto aquisição Uniformes/Mochila','Evento de desconto','EN: Uniform/Backpack Purchase Discount; ES: Descuento Compra de Uniformes/Mochila.'],['Desconto aquisição Campanha Vacinação','Evento de desconto','EN: Vaccination Campaign Purchase Discount; ES: Descuento Compra Campaña de Vacunación.'],['Desconto Aquisição Ingressos GNC Cinemas','Evento de desconto','EN: GNC Cinemas Ticket Purchase Discount; ES: Descuento Compra de Entradas GNC Cinemas.'],['Desconto Treinamentos DHO (feiras/congressos/cursos)','Evento de desconto','EN: DHO Training Discount (Fairs/Conferences/Courses); ES: Descuento Capacitaciones DHO (Ferias/Congresos/Cursos).'],['Desconto compras Encomendas Chocolate Brasil Cacau','Evento de desconto','EN: Brasil Cacau Chocolate Orders Purchases Discount; ES: Descuento Compras de Pedidos de Chocolate Brasil Cacau.'],['Descontos Diversos','Evento de desconto','EN: Miscellaneous Discounts; ES: Descuentos Varios.'],['Desconto compras Feiras Cacau Show','Evento de desconto','EN: Cacau Show Fair Purchases Discount; ES: Descuento Compras en Ferias Cacau Show.'],['Mensalidade Plano Odontológico - Prodent','Evento de desconto','EN: Prodent Dental Plan Monthly Fee; ES: Cuota Mensual Plan Odontológico - Prodent.'],['Desconto Despesas de viagem excedidas','Evento de desconto','EN: Exceeded Travel Expenses Discount; ES: Descuento Gastos de Viaje Excedidos.'],['Desconto Multas de Transito','Evento de desconto','EN: Traffic Fines Discount; ES: Descuento Multas de Tránsito.'],['Desconto Lavação Tijucas','Evento de desconto','EN: Tijucas Car Wash Discount; ES: Descuento Lavado Tijucas.'],['Descontos Adiantamentos extras (avulsos)','Evento de desconto','EN: Extra Advances Discount (One-Off); ES: Descuento Anticipos Extras (Puntuales).'],['Desconto Aquisição Imobilizado','Evento de desconto','EN: Fixed Asset Acquisition Discount; ES: Descuento Adquisición de Activo Fijo.'],['BU, PLR, DTM, PMC, DHO, CC, COO, CFO, CRM, SAP, OHD, R&S, WF, FI002','Preservar sigla','DHO = Desenvolvimento Humano e Organizacional (a empresa usa abreviado). WF = workflow (ex.: WF Rechazado, WF abierto por el Director Comercial). CFO e COO: ver pendências. (ES)'],['OR, XOR, AUX, OID, PIX','Preservar sigla','Inclusivo (OR), Exclusivo (XOR); AUX em nomes de campo (Nombre tipo de gasto AUX); PIX é o sistema de pagamento brasileiro. (ES)'],['workflow','Preservar','Todos usam o termo workflow. (ES)'],['Store, Cloud, Expert, Job, Legal (setor), add-on','Preservar','Store = nome de setor. Cloud mantido. Expert = como a empresa chama o colaborador (Reclutar Expert, Mochila Expert, Portal del Expert Brasil). Job mantido (Abrir solicitud de Job). Add-on mantido. (ES)'],['OpenMeter, front end, tenant, meter, feature_key, COUNT, SUM, MONTH, YEAR','Preservar','Termos técnicos e valores fixos de sistema (campos de seleção). Não traduzir valores fixos. (ES)'],['SoftExpert, SE Suite, Teams, Pipedrive, Kanban, Customer (nome do formulário)','Preservar nomes','Customer só fica em inglês quando for o nome do formulário; em frase comum, usar “cliente” (Análisis del borrador del cliente). (ES)'],['Gateway, gtwy, end_xor','Preservar','Termos de modelagem de processo. Pendente confirmar end_xor. (ES)'],['R$, BRL, USD, nomes de tabela/campo','Preservar','Manter valores no formato original (R$ 80,00). (ES)'],['Role','Decidido para ES','ES: Cargo. Sempre refere-se ao cargo da pessoa.'],['Receipt','Decidido para ES','ES: Recibo. Não usar “Comprobante” para Receipt (Proof of reimbursement transfer = Comprobante de transferencia del reembolso).'],['Return','Depende do contexto','ES: Retorno de viagem = Regreso; devolver solicitação/botão = Devolver (Devolver al solicitante); retorno técnico de etapa = retorno.'],['Caixa (box no formulário)','Decidido para ES','ES: Recuadro. Organização visual do formulário.'],['Partner (parceria)','Decidido para ES','ES: aliado. Datos de facturación del cliente / aliado.'],['Payment slip','Decidido para ES','ES: boleta de pago. Número de la boleta de pago. Boleto fica para passagens (Boleto de avión, de autobús).'],['Link (enviar) / Link (receber)','Decidido para ES','ES: Enlace (enviar) / Enlace (recibir) Ambos no infinitivo.'],['Extract / Extract data from receipt','Decidido para ES','ES: Extracción / Extraer datos del recibo. Extract como rótulo = Extracción.'],['Data','Decidido para ES','ES: Datos / Fecha. “Data (de dados)” = Datos; “Data (de date)” = Fecha.'],['Justa causa','Decidido para ES','ES: causa justa. Terminación del contrato de trabajo por causa justa.'],['Agreement','Decidido para ES','ES: Contrato. Contrato de licenciamiento y soporte; Contrato de confidencialidad.'],['Parcelamento','Decidido para ES','ES: cuotas. Forma mais natural.'],['Notify desl','Decidido para ES','ES: Notificar desvinculación. Sempre.'],['Título / Titulo / Title02','Decidido para ES','ES: Título / Título02. Com acento; Title02 vira Título02.'],['Reprovado (WF) / Reject / Reprovar','Decidido para ES','ES: WF Rechazado / Rechazar. Para WF usar Rechazado.'],['Approve / Aprovar; “Aprova” (rótulo)','Decidido para ES','ES: Aprobar; Aprueba. Aprova como rótulo = Aprueba.'],['Pricing Details','Decidido para ES','ES: Detalles de precios. Fixo.'],['Orientações sobre Termos / Guidelines on Terms','Decidido para ES','ES: Pautas sobre los términos. Fixo.'],['Add-on, Add','Decidido para ES','ES: Agregar (verbo) Também: Delete/Excluir = Eliminar.'],['Scorecard','Glossário ES','ES: cuadro de mando. Meta, peso mínimo, plan de acción, plazo (deadline), Responsable principal.'],['Compliance / Cumprimento','Glossário ES','ES: Cumplimiento. Canal de denuncias para Whistleblower Channel (pendente).'],['Feedback','Glossário ES','ES: retroalimentación. Calificación de la retroalimentación.'],['Reimbursement / Advance payment','Glossário ES','ES: Reembolso / Anticipo. Monto solicitado, Monto total, Monto disponible, Monto convertido a BRL/USD.'],['Exchange rate / Taxa de câmbio','Glossário ES','ES: Tipo de cambio. Fecha de cambio; Moneda de pago / Moneda utilizada.'],['Traveler / Reservations / Supplier','Glossário ES','ES: Viajero / Reservas / Proveedor. Solicitud de viaje; Informe de gastos; Boletos (passagens) de avión, autobús, tren; Alquiler de vehículo.'],['Termination / Rescisão','Glossário ES','ES: terminación. Iniciativa de terminación; Solicitar terminación del contrato.'],['Advertência escrita / verbal','Glossário ES','ES: Amonestación escrita / verbal. Suspensión temporal; Muy grave / Grave / Poco grave.'],['Urgência / High, Medium, Low','Glossário ES','ES: Urgencia / Alta, Media, Baja. Matriz GUT: Gravedad, Urgencia, Tendencia.'],['Addendum / Service rendering','Glossário ES','ES: Adenda / Prestación de servicios. Contratos.'],['Approver / Initiator / Recruiter','Glossário ES','ES: Aprobador / Iniciador / Reclutador. Cost Center Manager = Gerente de centro de costos; Project manager = Gerente de proyecto.'],['Chief Financial / Operation Officer; Head of HR','Glossário ES','ES: Director Financiero (CFO); Director de Operaciones (COO); Head de Recursos Humanos. Depende do contexto (ver seção 4).'],['Ingresso (cinema)','Glossário ES','ES: boleto. Ingressos GNC Cinemas = Boletos de GNC Cinemas. Portal del Expert Brasil - Convenios.'],['13º salário / abono de férias','Glossário ES','ES: aguinaldo (13.º salario) / convertir en efectivo hasta 1/3 de vacaciones. Depende do contexto (ver seção 4).'],['Board','Depende do contexto','ES: Junta pode soar como “reunião”; alternativas: Dirección, Directorio. Avaliar pelo uso no formulário.'],['Gold / Platinum / Standard','Depende do contexto','ES: Níveis de classificação: manter em inglês ou traduzir (Oro, Platino, Estándar), conforme o uso.'],['CFO / COO','Depende do contexto','ES: Director Financiero (CFO) / Director de Operaciones (COO), ou só a sigla (como em “Approve COO - BU”).'],['Whistleblower Channel','Depende do contexto','ES: Canal de denuncias ou manter em inglês.'],['Approve/Request Legal Analysis','Depende do contexto','ES: análisis jurídico, ou análisis Legal se Legal for nome de setor.'],['Start / End; Finalizador; Accidental; Sponsor; Registration; Boletos vs Entradas; end_xor','Depende do contexto','ES: Start/End: Inicio/Fin (substantivo) ou Iniciar/Finalizar (botão). Registration: Matrícula (colaborador) ou Registro. Sponsor: Patrocinador ou manter. Boletos/Entradas para ingressos. end_xor: manter ou fin_xor.'],['Abono de férias / 13º salário','Depende do contexto','ES: convertir en efectivo hasta 1/3 de vacaciones; aguinaldo (13.º salario). Se houver dúvida, perguntar em português.']];
function glossaryPage(){return header('Glossário e padrões','Referências iniciais que acompanham o contexto nas análises com IA.','','REGRAS DE NOMENCLATURA')+`<div class="grid-2"><section class="section-card"><h2>Como cada nome é tratado</h2><ul class="rule-list"><li>${icon('layers')}<div><strong>Processos</strong>Preferir ação no infinitivo em PT e ES, e verbo na forma base em EN, preservando a etapa real do processo.</div></li><li>${icon('form')}<div><strong>Formulários</strong>Usar títulos claros. Uma ação só é necessária quando fizer sentido para o formulário.</div></li><li>${icon('fields')}<div><strong>Campos, listas e grids</strong>Preservar rótulos nominais como Área, Data e Responsável. Revisar separadamente os termos internos de lista/grid.</div></li><li>${icon('shield')}<div><strong>Identificadores técnicos</strong>Confirmar se o texto é um código interno ou um rótulo apresentado ao usuário antes de traduzir.</div></li></ul></section><section class="section-card"><h2>O significado vem primeiro</h2><p>Quando as versões descrevem ações diferentes, a revisão fica pendente de contexto.</p><div class="reason-box"><h3>${icon('alert')}Exemplo real · FI006</h3><p>O original diz “Criar Orçamento”, enquanto PT e ES dizem “Gerenciar/Administrar Orçamento”. É preciso confirmar a ação e o sentido de orçamento antes de aplicar.</p></div><p>Alterações aprovadas preservam o texto importado e podem ser desfeitas pelo histórico.</p></section></div><section class="section-card data-card"><h2>Termos de referência</h2><div class="table-wrap"><table class="simple-table"><thead><tr><th>Termo</th><th>Tratamento</th><th>Contexto</th></tr></thead><tbody>${glossary.map(g=>`<tr>${g.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function historyPage(){return header('Histórico de revisão','Consulte as mudanças e restaure os valores anteriores quando necessário.',history.length?btn(icon('download')+'Exportar cópia','backup')+btn('Script dos revisados','sql-reviewed','primary'):'','RASTREABILIDADE')+`<section class="panel panel-space">${history.length?history.slice().reverse().slice(0,100).map(h=>`<div class="history-item"><span class="history-mark">${icon(h.action==='Desfeito'?'history':'check')}</span><div><strong>${esc(h.id||'Sem ID')} · ${esc(h.action)}</strong><p>${esc(h.before?.current?.original??'')} ${icon('arrow')} ${esc(h.after?.current?.original??'')}</p><small>${date(h.at)} · ${KINDS[h.kind]}${h.note?' · '+esc(h.note):''}</small></div>${h.action==='Aprovação'&&!h.undone&&byKey(h.recordKey)&&history.filter(x=>x.recordKey===h.recordKey).at(-1)?.key===h.key?btn('Desfazer','undo','',`data-key="${esc(h.key)}"`):''}</div>`).join(''):`<div class="empty"><div class="empty-art">${icon('history')}</div><h2>As próximas revisões ficam registradas aqui</h2><p>Abra um processo, revise as três sugestões e aprove para criar o primeiro registro.</p>${btn('Revisar CL002 '+icon('arrow'),'pilot','primary')}</div>`}</section>`;}
function close(){if(job?.running){toast('A análise continua. Use Parar após este grupo para encerrar.');return;}importer?.terminate();importer=null;overlay.innerHTML='';document.body.style.overflow='';lastFocus?.focus?.({preventScroll:true});}
function show(html){lastFocus=document.activeElement;overlay.innerHTML=html;document.body.style.overflow='hidden';requestAnimationFrame(()=>overlay.querySelector('button,input,select,textarea')?.focus({preventScroll:true}));}
function modal(title,body,footer=''){return `<div class="modal-scrim"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Fechar">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`;}
function comparison(r,list=false){const current=list?r.list:r.current,suggested=list?r.analysis?.listSuggested:r.analysis?.suggested;return LANGS.map((k,i)=>`<div class="compare-row"><div class="compare-title"><span class="lang">${['EN','PT','ES'][i]}</span>${list?'Termo da lista/grid':k==='original'?'Nome original em inglês':k==='pt'?'Nome em português':'Nome em espanhol'}</div><div class="compare-values"><div class="old-text">${clean(current[k])?esc(current[k]):'<span class="empty-value">Não preenchido</span>'}</div><textarea class="suggestion-input" id="${list?'list-':''}suggest-${k}" aria-label="${list?'Sugestão para lista/grid':'Sugestão'} ${['inglês','português','espanhol'][i]}" rows="2">${esc(suggested?.[k]??'')}</textarea></div></div>`).join('');}
function review(key){const r=byKey(key);if(!r)return;const problems=issues(r,idx);const needsContext=r.analysis?.needsContext||idx.conflictKeys.has(r.key);show(`<div class="scrim"><section class="drawer" role="dialog" aria-modal="true" aria-label="Revisar ${esc(r.id||'linha '+r.line)}"><header class="drawer-head"><div><div class="eyebrow">${KINDS[r.kind]} · ${r.id?'ID '+esc(r.id):'Linha '+r.line}</div><h2>${esc(r.current.pt||r.current.original||'Nome não preenchido')}</h2><span class="badge ${status(r,idx)}">${STATUS[status(r,idx)]}</span></div><button class="icon-button" data-action="close" aria-label="Fechar revisão">${icon('close')}</button></header><div class="drawer-body"><div class="context-box">${icon('link')}<strong>${r.kind==='process'?'Processo '+esc(r.id):esc(r.type)}</strong>${r.kind!=='process'?`<span>Processos: ${esc(r.processIds.join(', ')||'não informado')}</span>`:''}${r.kind==='field'?`<span>Formulários: ${esc(r.formIds.join(', ')||'não informado')}</span>`:''}${r.kind!=='field'?`<button class="tiny-btn" data-action="children" data-key="${esc(r.key)}">Ver ${r.kind==='process'?'formulários':'campos'} ${icon('arrow')}</button>`:''}</div><div class="reason-box"><h3>${icon('spark')}${r.analysis?'Motivo da revisão':'Verificação de preenchimento'}</h3><p>${esc(r.analysis?.reason??'O preenchimento e os vínculos foram conferidos. Preencha as sugestões manualmente ou conecte a IA para avaliar o significado no contexto do processo e formulário.')}</p>${r.analysis?`<small>${esc(r.analysis.provenance)}${r.analysis.at?' · '+date(r.analysis.at):''}<br>${esc(r.analysis.scope??'Revisão conforme o contexto enviado.')}</small>`:''}</div>${problems.length?`<ul class="issue-list">${problems.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}<div class="compare-labels"><span>Texto atual</span><span>Sugestão editável</span></div>${comparison(r)}${LANGS.some(k=>clean(r.list[k]))?`<h3 class="divider-title">Termos da lista/grid</h3>${comparison(r,true)}`:''}${needsContext?`<label class="context-confirm"><input id="context-confirm" type="checkbox" ${r.approval?.contextConfirmed?'checked':''}><span>Conferi a finalidade do processo e confirmei que estas sugestões preservam o significado correto.</span></label>`:''}<label class="field-label" for="review-note">Observação do revisor${needsContext?' (obrigatória para confirmar contexto)':''}</label><textarea id="review-note" class="input" rows="2" placeholder="Registre o contexto ou motivo do ajuste…">${esc(r.approval?.note??'')}</textarea><div class="source-note">Origem: ${esc(r.file)} · aba ${esc(r.sheet)} · linha ${r.line}.<br>Texto importado: ${esc(r.source.original||'não preenchido')}. Os identificadores permanecem preservados.</div><div id="review-error"></div></div><footer class="drawer-foot">${btn('Manter pendente','close')}${btn(icon('check')+(queue.length>1?'Aprovar e continuar':'Aprovar revisão'),'approve','primary',`data-key="${esc(r.key)}"`)}</footer></section></div>`);}
function connection(){show(modal('Conexão da IA',`<p>${live?'O servidor está conectado. Você pode analisar o filtro, registros selecionados ou um processo completo.':`A base contém ${n(count('process'))} processos, ${n(count('form'))} registros de formulários e ${n(count('field'))} registros de campos. As sugestões abrangem processos, formulários e campos. Casos sem tradução confiável estão sinalizados para revisão.`}</p><div class="config-note"><p><strong>${live?'IA ao vivo disponível':'IA ao vivo ainda não conectada'}</strong>${live?`<br>Modelo configurado: ${esc(liveModel)}`:''}</p><p>Preenchimento e vínculos são verificados localmente. Novas análises de significado usam o provedor de IA configurado no servidor.</p><p>Você pode revisar, editar, aprovar e exportar os nomes atuais. Os registros sem revisão semântica são identificados como pendentes, mesmo quando os três idiomas estão preenchidos.</p></div>`,btn('Fechar','close')+btn('Revisar sugestões','review-from-connection','primary')));}

function beginImport(k){importData={kind:k,file:null,sheet:'',headers:[],map:{},count:0,sample:[],replace:false};show(modal(`Importar ${KINDS[k].toLowerCase()}`,`<p>Selecione a planilha e confira o vínculo entre os identificadores e os nomes nos três idiomas.</p><label class="dropzone" id="dropzone">${icon('upload')}<strong>Escolha uma planilha ou arraste aqui</strong><small>XLSX, XLS ou CSV · até 32 MB</small><input id="import-file" type="file" accept=".xlsx,.xls,.csv" hidden></label><div id="import-preview"></div>`,btn('Cancelar','close')+btn('Importar registros','confirm-import','primary','id="confirm-import" disabled')));}
async function readFile(file){if(!file||file.size>32*1024*1024){toast('Selecione um arquivo de até 32 MB.');return;}importData.file=file.name;$('#dropzone').innerHTML=`${icon('form')}<strong>${esc(file.name)}</strong><small>Conferindo abas e colunas…</small>`;importer=new Worker('./import-worker.mjs',{type:'module'});importer.onerror=()=>{$('#import-preview').innerHTML='<div class="inline-error">Não foi possível carregar a planilha. Feche e tente novamente.</div>';};importer.onmessage=async event=>{const m=event.data;if(m.type==='sheets')importData.sheets=m.sheets;if(m.type==='preview'){Object.assign(importData,m);importPreview();}if(m.type==='error'){const target=$('#import-preview');if(target)target.innerHTML=`<div class="inline-error">${esc(m.message)}</div>`;$('#confirm-import')?.removeAttribute('disabled');}if(m.type==='records'){try{const events=[];const old=records.filter(r=>r.kind===importData.kind);const meta={key:crypto.randomUUID(),kind:importData.kind,file:importData.file,count:m.records.length,at:new Date().toISOString()};const previousImports=[...imports];imports=importData.replace?imports.filter(i=>i.kind!==importData.kind):imports;imports.push(meta);try{await save(m.records,events,true,importData.replace?importData.kind:null);}catch(e){imports=previousImports;throw e;}records=importData.replace?records.filter(r=>r.kind!==importData.kind):records;records=records.concat(m.records);touch();kind=importData.kind;view='catalog';page=1;query='';state='all';problem='all';selected.clear();close();render();toast(`${n(m.records.length)} registros importados. Nenhuma linha foi descartada por falta de ID.`);}catch(e){$('#import-preview').innerHTML=`<div class="inline-error">Importação não concluída: ${esc(e.message)}</div>`;$('#confirm-import').disabled=false;}}};const buffer=await file.arrayBuffer();importer.postMessage({action:'read',buffer,kind:importData.kind},[buffer]);}
function importPreview(){const d=importData,fields=[['id','Identificador do registro'],['original','Nome original (coluna EN)'],['pt','Nome PT'],['es','Nome ES'],...(d.kind!=='process'?[['process','Vínculo: ID Processo']]:[]),...(d.kind==='field'?[['form','Vínculo: ID Formulário'],['type','Tipo de elemento'],['listOriginal','Termo original (Lista/Grid)'],['listPt','Termo PT (Lista/Grid)'],['listEs','Termo ES (Lista/Grid)']]:[])];$('#import-preview').innerHTML=`<label class="field-label" for="import-sheet" style="margin-top:20px">ABA DA PLANILHA</label><select class="input" id="import-sheet">${options(d.sheets.map(s=>[s,s]),d.sheet)}</select><p class="import-message">${n(d.count)} linhas encontradas. Revise o mapeamento abaixo.</p><div class="mapping-grid">${fields.map(([k,l])=>`<label><span class="field-label">${l}</span><select class="input" data-map="${k}">${options([['','Não informado'],...d.headers.map((h,i)=>[String(i),h||'Coluna '+(i+1)])],d.map[k])}</select></label>`).join('')}</div><label class="import-mode"><input id="replace-kind" type="checkbox"><span>Substituir a base de ${KINDS[d.kind].toLowerCase()} existente (${n(count(d.kind))} registros). As demais bases serão preservadas.</span></label><div class="mapping-preview"><table><thead><tr>${d.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${d.sample.map(row=>`<tr>${d.headers.map((_,i)=>`<td>${esc(row[i]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#confirm-import').disabled=d.count===0||d.map.original==='';}
function exportFile(){const list=selected.size?selectedRecords():filter();if(!list.length){toast('Não há registros neste filtro.');return;}show(modal('Exportar revisão',`<p>A exportação inclui <strong>${n(list.length)} registros</strong> ${selected.size?'selecionados':'do filtro atual, de todas as páginas'}. Os nomes aprovados ocupam as colunas Nome original, Nome PT e Nome ES.</p><label class="import-mode"><input id="export-source" type="checkbox" checked><span>Preservar o formato e as colunas da planilha de origem.</span></label><label class="import-mode"><input id="export-suggestions" type="checkbox" checked><span>Incluir sugestões, motivos, status e textos importados para comparação.</span></label>`,btn('Cancelar','close')+btn(icon('download')+'Gerar XLSX','confirm-export','primary')));}
async function generateExport(){const list=selected.size?selectedRecords():filter(),worker=new Worker('./import-worker.mjs',{type:'module'});$('#overlay [data-action="confirm-export"]').disabled=true;worker.onmessage=e=>{if(e.data.type==='exported'){download(new Blob([e.data.buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`LexiFlow_${KINDS[kind]}_${new Date().toISOString().slice(0,10)}.xlsx`);worker.terminate();close();toast('Planilha exportada com os nomes e a revisão.');}else if(e.data.type==='error'){toast(e.data.message);worker.terminate();$('#overlay [data-action="confirm-export"]').disabled=false;}};worker.onerror=()=>{toast('Não foi possível gerar a exportação.');worker.terminate();$('#overlay [data-action="confirm-export"]').disabled=false;};worker.postMessage({action:'export',records:list.map(r=>({...r,validationStatus:status(r,idx),validationReason:r.analysis?.reason||issues(r,idx).join(' ')||'Sem revisão semântica.'})),suggestions:$('#export-suggestions').checked,sourceLayout:$('#export-source').checked});}
function openSQL(fromHistory=false){const reviewed=k=>idx.byKind[k].filter(r=>r.approval).length,startKind=fromHistory?(kind!=='field'&&reviewed(kind)?kind:reviewed('process')||!reviewed('form')?'process':'form'):kind;show(modal(fromHistory?'Script dos registros revisados':'Script para atualização',`<p>${fromHistory?'Gere um script PostgreSQL só com os registros aprovados na revisão. Registros desfeitos não entram.':'Gere um script PostgreSQL com as sugestões da aba atual.'} Cada destino é atualizado uma vez, mesmo que esteja vinculado a vários processos.</p>${fromHistory?`<label class="field-label" for="sql-kind">TIPO</label><select class="input" id="sql-kind">${options([['process',`Processos (${n(reviewed('process'))} revisados)`],['form',`Formulários (${n(reviewed('form'))} revisados)`]],startKind)}</select>`:''}<label class="field-label" for="sql-scope">ESCOPO</label><select class="input" id="sql-scope">${fromHistory?options([['approved','Somente registros revisados (aprovados)']],'approved'):options([['all',`Toda a base de ${KINDS[kind].toLowerCase()}`],['filter',`Filtro atual, todas as páginas (${n(filter().length)})`],['approved',`Somente registros revisados (${n(reviewed(kind))})`]],process||form||query||state!=='all'?'filter':'all')}</select><label class="import-mode"><input type="checkbox" id="sql-context"><span>Incluir sugestões que exigem confirmação de contexto. Conferirei os nomes indicados antes de executar.</span></label><div class="config-note">Atualiza apenas nomes EN/PT/ES na revisão atual. Inclui idiomas ausentes quando o schema permite inserção. As chaves/colunas obrigatórias não informadas pela consulta são verificadas pelo script. Execute primeiro em homologação com o DBA; este portal gera o arquivo e não acessa o banco.</div><div id="sql-summary"></div><label class="field-label" for="sql-preview" style="margin-top:16px">PRÉVIA DO SCRIPT</label><textarea id="sql-preview" class="input sql-preview" readonly spellcheck="false" aria-label="Script SQL"></textarea>`,btn('Atualizar prévia','refresh-sql')+btn('Copiar script','copy-sql')+btn(icon('download')+'Baixar .sql','download-sql','primary')));refreshSQL();}
function sqlKind(){return $('#sql-kind')?.value||kind;}
function refreshSQL(){const k=sqlKind(),scope=$('#sql-scope').value,list=scope==='approved'?idx.byKind[k].filter(r=>r.approval):scope==='all'?idx.byKind[k]:filter(),plan=generateSQL(list,k,{includeContext:$('#sql-context').checked});window.sqlDraft=plan;$('#sql-preview').value=plan.sql;$('#sql-summary').innerHTML=`<div class="notice"><span><strong>${n(plan.entries.length)} destinos únicos</strong> de ${n(plan.sourceRows)} linhas. ${n(plan.skipped.length)} exclusões por contexto, tradução incompleta ou conflito. Os motivos constam no script.</span></div>`;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function needsContextFor(r){return r.analysis?.needsContext||idx.conflictKeys.has(r.key);}
function eligible(r){return canBulkApprove(r,idx);}
function bulkApprove(){const list=selectedRecords(),ready=list.filter(eligible);show(modal('Aprovar sugestões selecionadas',`<p><strong>${n(ready.length)} de ${n(list.length)} registros</strong> têm sugestões sem dúvidas de contexto e sem problemas de identificação ou preenchimento.</p><p>Os nomes atuais serão substituídos pelas sugestões EN, PT e ES. Os valores anteriores ficarão registrados no histórico.</p><div class="config-note">Registros com dúvidas de contexto precisam ser revisados individualmente.</div>`,btn('Cancelar','close')+btn(`Aprovar ${n(ready.length)} sugestões`,'confirm-bulk','primary',ready.length?'':'disabled')));}
async function commitReview(key){const r=byKey(key);if(!r)return;try{const suggested=Object.fromEntries(LANGS.map(k=>[k,$('#suggest-'+k).value])),hasList=LANGS.some(k=>clean(r.list[k])),listSuggested=hasList?Object.fromEntries(LANGS.map(k=>[k,$('#list-suggest-'+k).value])):null,note=$('#review-note').value,confirmed=$('#context-confirm')?.checked??false;if(needsContextFor(r)&&!clean(note))throw new Error('Registre uma observação para confirmar o contexto.');const next=structuredClone(r);if(needsContextFor(r)&&!confirmed)throw new Error('Confirme o contexto antes de aprovar.');if(needsContextFor(r)&&!clean(note))throw new Error('Registre uma observação para confirmar o contexto.');const event=approve(next,suggested,listSuggested,{contextConfirmed:confirmed,note});await save([next],[event]);records[records.indexOf(r)]=next;touch();history.push(event);const idx=queue.indexOf(key),nextKey=queue[idx+1];queue=queue.filter(k=>k!==key);close();render();toast('Revisão aprovada. Textos anteriores preservados.');if(nextKey&&byKey(nextKey))review(nextKey);}catch(e){$('#review-error').innerHTML=`<div class="inline-error">${esc(e.message)}</div>`;}}
async function commitBulk(){const list=selectedRecords().filter(eligible),changed=[],events=[];try{for(const r of list){const next=structuredClone(r);const event=approve(next,next.analysis.suggested,next.analysis.listSuggested);changed.push(next);events.push(event);}await save(changed,events);const map=new Map(changed.map(r=>[r.key,r]));records=records.map(r=>map.get(r.key)??r);touch();history.push(...events);selected.clear();close();render();toast(`${n(changed.length)} sugestões aprovadas.`);}catch(e){toast('Não foi possível aprovar: '+e.message);}}
async function undo(key){const h=history.find(x=>x.key===key),r=byKey(h?.recordKey);if(!h||!r)return;if(history.filter(x=>x.recordKey===r.key).at(-1)?.key!==key){toast('Desfaça primeiro a alteração mais recente desse registro.');return;}const next=structuredClone(r);Object.assign(next,structuredClone(h.before));next.revision++;const oldEvent={...h,undone:true};const event={key:crypto.randomUUID(),recordKey:r.key,id:r.id,kind:r.kind,action:'Desfeito',before:{current:structuredClone(r.current)},after:{current:structuredClone(next.current)},at:new Date().toISOString(),note:'Valores anteriores restaurados.'};try{await save([next],[oldEvent,event]);records[records.indexOf(r)]=next;touch();history[history.indexOf(h)]=oldEvent;history.push(event);render();toast('Valores anteriores restaurados.');}catch(e){toast('Não foi possível desfazer: '+e.message);}}
function analysisScope(mode='current'){if(mode==='process'&&process)return [idx.processes.get(process),...(idx.formsByProcess.get(process)||[]),...(idx.fieldsByProcess.get(process)||[])].filter(Boolean);if(mode==='form'&&form)return [...(idx.forms.get(form)||[]).filter(r=>!process||r.processIds.includes(process)),...filtered(records,{kind:'field',process,form})];return selected.size?selectedRecords():filter();}
function beginAnalysis(){if(!live){connection();return;}const scope=analysisScope();if(!scope.length){toast('Não há registros para analisar.');return;}const choices=[['current',`${selected.size?'Registros selecionados':'Filtro atual, todas as páginas'} · ${n(scope.length)} registros`],...(process?[['process',`Processo completo ${process} · ${n(analysisScope('process').length)} registros`]]:[]),...(form?[['form',`Formulário ${form} e seus campos · ${n(analysisScope('form').length)} registros`]]:[])];show(modal('Analisar seleção com IA',`<p>A análise considera nomes, tipo de elemento, processo e formulário. As três listas reais estão disponíveis para compor o contexto.</p><label class="field-label" for="ai-scope">ESCOPO DA ANÁLISE</label><select id="ai-scope" class="input">${options(choices,process&&kind==='process'?'process':'current')}</select><div class="config-note" style="margin-top:16px">As sugestões serão atualizadas sem alterar os nomes atuais. Os textos do escopo escolhido serão enviados ao provedor configurado e podem gerar custos de API.</div><label class="import-mode"><input id="only-pending" type="checkbox" checked><span>Analisar apenas registros que ainda não têm revisão semântica.</span></label><div id="job-progress"></div>`,btn('Cancelar','close')+btn(icon('spark')+'Iniciar análise','run-analysis','primary')));}

function contextualRecord(r){const pids=r.kind==='process'?[r.id]:r.processIds,parents=pids.map(p=>idx.processes.get(p)).filter(Boolean);for(const f of r.formIds)parents.push(...(idx.forms.get(f)||[]).filter(x=>!pids.length||x.processIds.some(p=>pids.includes(p))));return {key:r.key,kind:r.kind,id:r.id,sourceLine:r.line,type:r.type,current:r.current,list:r.list,processIds:r.processIds,formIds:r.formIds,parents:parents.map(x=>({kind:x.kind,id:x.id,names:x.current})),exportedContext:r.rawSchema==='fields-v1'?{process:{original:r.raw[3],pt:r.raw[2],es:r.raw[1]},form:{original:r.raw[5],pt:r.raw[6],es:r.raw[7]}}:null,structuralIssues:issues(r,idx).filter(x=>/Identificador|vínculo|divergentes|par processo|limite observado/.test(x))};}

async function runAnalysis(){const scope=analysisScope($('#ai-scope').value).filter(r=>!$('#only-pending').checked||!r.analysis||!!r.analysis.method);if(!scope.length){toast('Todos os registros desta seleção já têm revisão. Desmarque a opção para reanalisar.');return;}job={running:true,stop:false,total:scope.length,done:0};$('#only-pending').disabled=true;$('#ai-scope').disabled=true;const startButton=$('#overlay [data-action="run-analysis"]');startButton.disabled=true;$('#overlay [data-action="close"]').disabled=true;function progress(error=''){$('#job-progress').innerHTML=`<div class="progress-wrap"><div class="progress-title"><span>${n(job.done)} de ${n(job.total)} analisados</span><span>${Math.round(job.done/job.total*100)}%</span></div><div class="progress-bar"><i style="width:${job.done/job.total*100}%"></i></div></div>${job.running?btn('Parar após este grupo','stop-job',''):''}${error?`<div class="inline-error">${esc(error)}. As análises já concluídas foram preservadas.</div>`:''}`;}
 progress();try{for(let i=0;i<scope.length&&!job.stop;i+=15){const batch=scope.slice(i,i+15),snapshots=new Map(batch.map(r=>[r.key,snapshot(r)]));const response=await fetch('./api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({records:batch.map(contextualRecord),glossary}),signal:AbortSignal.timeout(150000)});const body=await response.json();if(!response.ok)throw new Error(body.error??'Falha na análise');const revisions=validAnalysis(body,batch),changed=[];for(const result of revisions){const r=byKey(result.key);if(!r||snapshot(r)!==snapshots.get(r.key))continue;const next=structuredClone(r);next.analysis={...result,snapshot:structuredClone(r.current),provenance:'IA ao vivo · '+liveModel,at:new Date().toISOString(),scope:'Registros selecionados com contexto de processo e formulário.'};next.approval=null;next.rejected=false;next.revision++;changed.push(next);}await save(changed);const map=new Map(changed.map(r=>[r.key,r]));records=records.map(r=>map.get(r.key)??r);touch();job.done+=changed.length;progress();}job.running=false;progress();toast(job.stop?'Análise interrompida. Resultados concluídos preservados.':'Análise concluída. Revise as novas sugestões.');}catch(e){job.running=false;progress(e.message);}startButton.disabled=false;startButton.textContent='Analisar pendentes';$('#only-pending').disabled=false;$('#ai-scope').disabled=false;$('#overlay [data-action="close"]').disabled=false;render();}
async function restoreFile(file){try{if(!file||file.size>256*1024*1024)throw new Error('Selecione uma cópia JSON de até 256 MB.');const backup=JSON.parse(await file.text());if(backup.format!=='lexiflow-backup-v1'||!Array.isArray(backup.records)||!Array.isArray(backup.history)||!Array.isArray(backup.imports))throw new Error('Formato de cópia não reconhecido.');const keys=new Set();for(const r of backup.records){if(!r.key||keys.has(r.key)||!KINDS[r.kind]||typeof r.current?.original!=='string'||typeof r.current?.pt!=='string'||typeof r.current?.es!=='string'||!Array.isArray(r.processIds)||!Array.isArray(r.formIds)||!r.source||!r.list)throw new Error('A cópia contém registros inválidos.');keys.add(r.key);}window.pendingBackup=backup;show(modal('Restaurar cópia de segurança',`<p>Esta cópia contém ${n(backup.records.length)} registros e ${n(backup.history.length)} eventos. A base atual deste navegador será substituída.</p>`,btn('Cancelar','close')+btn('Restaurar cópia','confirm-restore','primary')));}catch(e){toast(e.message);}}
async function confirmRestore(){const backup=window.pendingBackup;if(!backup)return;try{if(!db)throw new Error('O armazenamento deste navegador está indisponível.');await new Promise((resolve,reject)=>{const tx=db.transaction(['records','history','meta'],'readwrite');for(const name of ['records','history','meta'])tx.objectStore(name).clear();for(const r of backup.records)tx.objectStore('records').put(r);for(const h of backup.history)tx.objectStore('history').put(h);tx.objectStore('meta').put({key:'imports',value:backup.imports});tx.objectStore('meta').put({key:'datasetId',value:backup.datasetId||datasetId});tx.objectStore('meta').put({key:'dataAudit',value:backup.dataAudit||dataAudit});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});records=backup.records;history=backup.history;imports=backup.imports;datasetId=backup.datasetId||datasetId;dataAudit=backup.dataAudit||dataAudit;touch();window.pendingBackup=null;process='';form='';selected.clear();close();render();toast('Cópia restaurada.');}catch(e){toast('Não foi possível restaurar: '+e.message);}}
function reset(){page=1;selected.clear();}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;try{
 if(a==='view'){view=el.dataset.value;render();}
 else if(a==='tab'){kind=el.dataset.kind;elementType='';view='catalog';if(kind==='process')form='';state='all';problem='all';query='';reset();render();}
 else if(a==='import')beginImport(el.dataset.kind||kind);
 else if(a==='mobile')$('.sidebar').classList.toggle('open');
 else if(a==='diagnostic'){view='catalog';kind=el.dataset.kind;process='';form='';query='';state='all';problem=el.dataset.problem;elementType='';reset();render();}
 else if(a==='pilot'){view='catalog';kind='process';process='CL002';form='';query='';state='all';problem='all';elementType='';reset();render();}
 else if(a==='back-process'){kind='process';form='';state='all';problem='all';reset();render();}
 else if(a==='reset-filter'){process='';form='';query='';state='all';problem='all';elementType='';reset();render();}
 else if(a==='problem'){problem=el.dataset.value;reset();render();}
 else if(a==='page'){page=Number(el.dataset.page);render();}
 else if(a==='select-row'){el.checked?selected.add(el.dataset.key):selected.delete(el.dataset.key);render();}
 else if(a==='select-page'){const list=filter().slice((page-1)*pageSize,page*pageSize);for(const r of list)el.checked?selected.add(r.key):selected.delete(r.key);render();}
 else if(a==='select-filter'){selected=new Set(filter().map(r=>r.key));render();}
 else if(a==='clear-selection'){selected.clear();render();}
 else if(a==='review'){queue=[el.dataset.key];review(el.dataset.key);}
 else if(a==='review-selection'){queue=selectedRecords().map(r=>r.key);if(queue.length)review(queue[0]);}
 else if(a==='review-from-connection'){close();view='catalog';render();const r=filter()[0];if(r){queue=[r.key];review(r.key);}}
 else if(a==='children'){const r=byKey(el.dataset.key);close();if(r.kind==='process'){process=r.id;form='';kind='form';}else{form=r.id;process=process||r.processIds[0]||'';kind='field';}view='catalog';query='';state='all';problem='all';elementType='';reset();render();}
 else if(a==='close')close();
 else if(a==='connection')connection();
 else if(a==='approve')await commitReview(el.dataset.key);
 else if(a==='bulk-approve')bulkApprove();
 else if(a==='confirm-bulk')await commitBulk();
 else if(a==='undo')await undo(el.dataset.key);
 else if(a==='export')exportFile();
 else if(a==='confirm-export')await generateExport();
 else if(a==='sql-script')openSQL();
 else if(a==='sql-reviewed')openSQL(true);
 else if(a==='refresh-sql')refreshSQL();
 else if(a==='download-sql'){download(new Blob([window.sqlDraft.sql],{type:'text/plain;charset=utf-8'}),`LexiFlow_${sqlKind()==='process'?'processos':'formularios'}_${$('#sql-scope')?.value==='approved'?'revisados_':''}atualizacao.sql`);}
 else if(a==='copy-sql'){try{await navigator.clipboard.writeText(window.sqlDraft.sql);toast('Script copiado.');}catch{toast('Selecione o texto para copiar o script.');}}
 else if(a==='backup'){download(new Blob([JSON.stringify({format:'lexiflow-backup-v1',datasetId,dataAudit,at:new Date().toISOString(),records,history,imports})],{type:'application/json'}),'LexiFlow_copia_'+new Date().toISOString().slice(0,10)+'.json');toast('Cópia de segurança exportada.');}
 else if(a==='confirm-import'){const d=importData;if(d.map.original==='')throw new Error('Selecione a coluna de Nome original.');d.replace=$('#replace-kind').checked;el.disabled=true;$('#import-preview').innerHTML='<div class="loading-inline"><span class="spinner"></span>Importando todas as linhas…</div>';importer.postMessage({action:'normalize',map:d.map,kind:d.kind,file:d.file,sheet:d.sheet,batchId:crypto.randomUUID()});}
 else if(a==='confirm-restore')await confirmRestore();
 else if(a==='analyze')beginAnalysis();
 else if(a==='run-analysis')await runAnalysis();
 else if(a==='stop-job'){job.stop=true;el.disabled=true;el.textContent='Interrompendo após este grupo…';}
 }catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;reset();render();}});
document.addEventListener('change',e=>{const el=e.target;
 if(['sql-kind','sql-scope','sql-context'].includes(el.id)){refreshSQL();return;}
 if(el.id==='process-filter'){process=el.value;form='';reset();render();}
 else if(el.id==='form-filter'){form=el.value;reset();render();}
 else if(el.id==='type-filter'){elementType=el.value;reset();render();}
 else if(el.id==='state-filter'){state=el.value;reset();render();}
 else if(el.id==='page-size'){pageSize=Number(el.value);page=1;render();}
 else if(el.id==='import-file')readFile(el.files[0]);
 else if(el.id==='restore-file')restoreFile(el.files[0]);
 else if(el.id==='import-sheet')importer.postMessage({action:'preview',sheet:el.value,kind:importData.kind});
 else if(el.dataset.map){importData.map[el.dataset.map]=el.value;$('#confirm-import').disabled=importData.map.original==='';}
});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone'))e.preventDefault();});
document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();readFile(e.dataTransfer.files[0]);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay.innerHTML)close();if(e.key==='Tab'&&overlay.innerHTML){const elements=[...overlay.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>x.getClientRects().length);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
async function removeObsoleteEmbedded(keep){if(!db)return;await new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');for(const r of records)if(isEmbedded(r)&&!keep.has(r.key))tx.objectStore('records').delete(r.key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function metaWrite(values){if(!db)return;await new Promise((resolve,reject)=>{const tx=db.transaction('meta','readwrite');for(const [key,value] of Object.entries(values))tx.objectStore('meta').put({key,value});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error??new Error('Falha ao salvar metadados.'));});}
function loading(done,total){app.innerHTML=`<div class="boot"><div class="brand-symbol">L</div><h1>Conectando sua base completa</h1><p>${n(done)} de ${n(total)} registros carregados</p><div class="progress-bar" style="width:280px"><i style="width:${total?done/total*100:0}%"></i></div><p style="font-size:11px">Processos, formulários e campos estão sendo preparados.</p></div>`;}
async function loadComplete(manifest){const existing=migrationIndex(records),merged=new Map(records.filter(r=>!isEmbedded(r)).map(r=>[r.key,r])),worker=new Worker('./seed-worker.mjs',{type:'module'}),url=new URL('./base.json',location.href).href;await new Promise((resolve,reject)=>{worker.onerror=()=>{worker.terminate();reject(new Error('Não foi possível preparar a base completa.'));};worker.onmessage=async e=>{try{const m=e.data;if(m.type==='error')throw new Error(m.message);if(m.type==='chunk'){const changed=mergeIncoming(m.records,existing);for(const r of changed)merged.set(r.key,r);await save(changed);loading(m.done,m.total);worker.postMessage({action:'next',url});}if(m.type==='complete'){await removeObsoleteEmbedded(new Set(merged.keys()));records=[...merged.values()];const baseNames=new Set(m.imports.map(i=>i.file));imports=[...imports.filter(i=>i.key!=='seed'&&!i.sourceId&&!baseNames.has(i.file)),...m.imports];datasetId=m.datasetId;dataAudit=m.audit;await metaWrite({datasetId,dataAudit,imports});worker.terminate();resolve();}}catch(error){worker.terminate();reject(error);}};worker.postMessage({action:'load',url});});}
async function init(){try{db=await openDB();const [saved,events,meta]=await Promise.all([readStore('records'),readStore('history'),readStore('meta')]);records=saved;history=events.sort((a,b)=>a.at.localeCompare(b.at));imports=meta.find(x=>x.key==='imports')?.value??[];datasetId=meta.find(x=>x.key==='datasetId')?.value??'';dataAudit=meta.find(x=>x.key==='dataAudit')?.value??null;}catch{storageOK=false;}
 try{const res=await fetch('./base.json',{cache:'no-cache'});if(!res.ok)throw new Error('Não foi possível abrir a base inicial.');const manifest=await res.json();if(datasetId!==manifest.datasetId||!records.length){loading(0,manifest.imports.reduce((s,i)=>s+i.count,0));await loadComplete(manifest);}touch();render();fetch('./api/status').then(r=>r.ok?r.json():null).then(s=>{live=s?.configured===true;liveModel=s?.model??'';if(live)render();}).catch(()=>{});}catch(e){app.innerHTML=`<div class="boot"><h1>Não foi possível concluir o carregamento</h1><p>${esc(e.message)}</p><p>As revisões anteriores foram preservadas.</p><button class="btn" onclick="location.reload()">Tentar novamente</button></div>`;}}
init();
